DAN_STATIC_STR(dan_lit_2142, "    if (r->sign) dan_not_exact(dan_big_to_str(a), dan_big_to_str(b), line);\n    return q;\n}\nstatic dan_big dan_big_mod(dan_big a, dan_big b, int line) { dan_big q, r; dan_big_divmod(a, b, &q, &r, line); return r; }\n\nstatic int dan_big_cmp(dan_big a, dan_big b) {\n    if (a->sign != b->sign) return a->sign < b->sign \? -1 : 1;\n    int c = dan_mag_cmp(a->d, a->n, b->d, b->n);\n    return a->sign < 0 \? -c : c;\n}\nstatic bool dan_big_eq(dan_big a, dan_big b) { return dan_big_cmp(a, b) == 0; }\n\nstatic dan_big dan_big_pow(dan_big a, int64_t e, int line) {\n    if (e < 0) {\n        if (a->n == 1 && a->d[0] == 1) return (a->sign > 0 || e % 2 == 0) \? dan_big_from_int(1) : a;\n        if (!a->sign) dan_error(DAN_MSG_DIV_ZERO, line);\n        dan_error(DAN_MSG_NEG_POW, line);\n    }\n    dan_big r = dan_big_from_int(1), x = a;\n    while (e > 0) {\n        if (e & 1) r = dan_big_mul(r, x, line);\n        e >>= 1;\n        if (e) x = dan_big_mul(x, x, line);\n    }\n    return r;\n}\n\nstatic int64_t dan_big_to_int(dan_big a, int line) {\n    if (a->n > 2) dan_error(DAN_MSG_BIG_TO_INT, line);\n    uint64_t m = a->n == 0 \? 0 : a->n == 1 \? a->d[0] : ((uint64_t)a->d[1] << 32) | a->d[0];\n    if (a->sign >= 0 \? m > (uint64_t)INT64_MAX : m > (uint64_t)INT64_MAX + 1) dan_error(DAN_MSG_BIG_TO_INT, line);\n    return a->sign < 0 \? (int64_t)((uint64_t)0 - m) : (int64_t)m;\n}\nstatic double dan_big_to_float(dan_big a) {\n    double r = 0;\n    for (int32_t i = a->n - 1; i >= 0; i--) r = r * 4294967296.0 + a->d[i];\n    return a->sign < 0 \? -r : r;\n}\n\nstatic dan_str dan_big_to_str(dan_big a) {\n    if (!a->sign) return dan_strdup(\"0\");\n    int32_t n = a->n;\n    uint32_t *t = dan_alloc(sizeof(uint32_t) * (size_t)n);\n    memcpy(t, a->d, sizeof(uint32_t) * (size_t)n);\n    size_t cap = (size_t)n * 10 + 2, len = 0;\n    char *buf = dan_alloc(cap);\n    while (n > 0) {\n        uint64_t k = 0;\n        for (int32_t j = n - 1; j >= 0; j--) {\n            uint64_t cur = (k << 32) | t[j];\n            t[j] = (uint32_t)(cur / 1000000000u);\n            k = cur % 1000000000u;\n        }\n        while (n > 0 && t[n - 1] == 0) n--;\n        for (int i = 0; i < 9 && (n > 0 || k); i++) { buf[len++] = (char)('0' + k % 10); k /= 10; }\n    }\n    if (a->sign < 0) buf[len++] = '-';\n    char *s = dan_str_new(len);\n    for (size_t i = 0; i < len; i++) s[i] = buf[len - 1 - i];\n    dan_free(t);\n    dan_free(buf);\n    return s;\n}\nstatic void dan_write_big(dan_big a) { fputs(dan_big_to_str(a), stdout); }\n\nstatic dan_big dan_big_from_str(dan_str s, int line) {\n    const char *p = s;\n    while (*p == ' ' || *p == '\\\\t') p++;\n    int neg = 0;\n    if (*p == '-' || *p == '+') neg = *p++ == '-';\n    size_t digits = 0;\n    for (const char *q = p; *q; q++) if (*q >= '0' && *q <= '9') digits++;\n    dan_big_s *r = dan_big_alloc((int64_t)(digits / 9 + 2));\n    memset(r->d, 0, sizeof(uint32_t) * (size_t)r->n);\n    int32_t used = 0, any = 0;\n    uint64_t chunk = 0, mult = 1;\n    for (;; p++) {\n        if (*p == '_' || *p == ' ') continue;\n        if (*p && (*p < '0' || *p > '9')) dan_conv_error(DAN_MSG_NOT_BIG, s, line);\n        if (*p) { any = 1; chunk = chunk * 10 + (uint64_t)(*p - '0'); mult *= 10; }\n        if (mult == 1000000000u || (!*p && mult > 1)) {\n            uint64_t c = chunk;\n            for (int32_t i = 0; i < used; i++) { c += (uint64_t)r->d[i] * mult; r->d[i] = (uint32_t)c; c >>= 32; }\n            if (c) r->d[used++] = (uint32_t)c;\n            chunk = 0; mult = 1;\n        }\n        if (!*p) break;\n    }\n    if (!any) dan_conv_error(DAN_MSG_NOT_BIG, s, line);\n    r->n = used;\n    r->sign = neg \? -1 : 1;\n    return dan_big_norm(r);\n}\n");
DAN_STATIC_STR(dan_lit_2143, "\n/* ---- profiler (python dan.py \320\277\321\200\320\276\321\204\320\270\320\273\321\214 \320\277\321\200\320\276\320\263\321\200\320\260\320\274\320\274\320\260.dan) ----\n   Every function of the program starts a frame and closes it automatically\n   at the end of its C scope (the cleanup attribute). A frame knows its\n   start time and the time spent in the functions it called, so each\n   function gets its own time (without callees) and its total time; for\n   recursive functions the total time counts only the outermost call.\n   Counters are shared by tasks and updated atomically. At exit the table is\n   written to the file named by the DAN_PROFILE environment variable. */\n\ntypedef struct dan_prof_frame { struct dan_prof_frame *parent; int id; uint64_t start, child; } dan_prof_frame;\ntypedef struct { uint64_t calls, total, self; } dan_prof_entry;\nstatic dan_prof_entry dan_prof[DAN_PROF_COUNT];\nstatic DAN_TLS dan_prof_frame *dan_prof_top;\nstatic DAN_TLS unsigned dan_prof_active[DAN_PROF_COUNT];\nstatic uint64_t dan_prof_begin;\n\nstatic uint64_t dan_prof_now(void) {\n#ifdef _WIN32\n    static LARGE_INTEGER freq;\n    LARGE_INTEGER c;\n    if (!freq.QuadPart) QueryPerformanceFrequency(&freq);\n    QueryPerformanceCounter(&c);\n    return (uint64_t)(c.QuadPart / freq.QuadPart) * 1000000000u\n         + (uint64_t)(c.QuadPart % freq.QuadPart) * 1000000000u / (uint64_t)freq.QuadPart;\n#else\n    struct timespec t;\n    clock_gettime(CLOCK_MONOTONIC, &t);\n    return (uint64_t)t.tv_sec * 1000000000u + (uint64_t)t.tv_nsec;\n#endif\n}\n\nstatic inline void dan_prof_enter(dan_prof_frame *f, int id) {\n    f->parent = dan_prof_top; f->id = id; f->child = 0;\n    dan_prof_active[id]++;\n    dan_prof_top = f;\n    f->start = dan_prof_now();\n}\n\nstatic inline void dan_prof_leave(dan_prof_frame *f) {\n    uint64_t spent = dan_prof_now() - f->start;\n    dan_prof_entry *e = &dan_prof[f->id];\n    __atomic_fetch_add(&e->calls, 1, __ATOMIC_RELAXED);\n    __atomic_fetch_add(&e->self, spent > f->child \? spent - f->child : 0, __ATOMIC_RELAXED);\n    if (--dan_prof_active[f->id] == 0) __atomic_fetch_add(&e->total, spent, __ATOMIC_RELAXED);\n    if (f->parent) f->parent->child += spent;\n    dan_prof_top = f->parent;\n}\n\nstatic void dan_prof_dump(void) {\n#ifdef _WIN32\n    /* the path may contain Cyrillic letters: the wide (UTF-16) variant does not depend on the code page */\n    const wchar_t *path = _wgetenv(L\"DAN_PROFILE\");\n    if (!path || !*path) return;\n    FILE *out = _wfopen(path, L\"wb\");\n#else\n    const char *path = getenv(\"DAN_PROFILE\");\n    if (!path || !*path) return;\n    FILE *out = fopen(path, \"wb\");\n#endif\n    if (!out) return;\n    fprintf(out, \"%\" PRIu64 \"\\n\", dan_prof_now() - dan_prof_begin);\n    for (int i = 0; i < DAN_PROF_COUNT; i++) {\n        int line = dan_prof_lines[i];\n        const char *file = dan_files[line >= DAN_FILE_STEP && line / DAN_FILE_STEP < DAN_FILE_COUNT \? line / DAN_FILE_STEP : 0];\n        fprintf(out, \"%s\\t%s\\t%d\\t%\" PRIu64 \"\\t%\" PRIu64 \"\\t%\" PRIu64 \"\\n\", dan_prof_names[i], file,\n                line % DAN_FILE_STEP, __atomic_load_n(&dan_prof[i].calls, __ATOMIC_RELAXED),\n                __atomic_load_n(&dan_prof[i].total, __ATOMIC_RELAXED), __atomic_load_n(&dan_prof[i].self, __ATOMIC_RELAXED));\n    }\n    fclose(out);\n}\n\nstatic void dan_prof_start(void) {\n    dan_prof_begin = dan_prof_now();\n    atexit(dan_prof_dump);\n}\n");
DAN_STATIC_STR(dan_lit_2144, "\n/* ---- test coverage (python dan.py \321\202\320\265\321\201\321\202\320\270\321\200\320\276\320\262\320\260\321\202\321\214 --\320\277\320\276\320\272\321\200\321\213\321\202\320\270\320\265) ----\n   Every statement of the program (not of the tests and not of the standard\n   library) sets its own flag; at exit the flags are written to the file\n   named by the DAN_COVERAGE environment variable: file, line, 0 or 1. */\n\nstatic void dan_cov_dump(void) {\n#ifdef _WIN32\n    const wchar_t *path = _wgetenv(L\"DAN_COVERAGE\");\n    if (!path || !*path) return;\n    FILE *out = _wfopen(path, L\"wb\");\n#else\n    const char *path = getenv(\"DAN_COVERAGE\");\n    if (!path || !*path) return;\n    FILE *out = fopen(path, \"wb\");\n#endif\n    if (!out) return;\n    for (int i = 0; i < DAN_COV_COUNT; i++) {\n        int line = dan_cov_lines[i];\n        if (line <= 0) continue;\n        const char *file = dan_files[line >= DAN_FILE_STEP && line / DAN_FILE_STEP < DAN_FILE_COUNT \? line / DAN_FILE_STEP : 0];\n        fprintf(out, \"%s\\t%d\\t%d\\n\", file, line % DAN_FILE_STEP, dan_cov[i] \? 1 : 0);\n    }\n    fclose(out);\n}\n");
DAN_STATIC_STR(dan_lit_2145, "\n/* ---- benchmarks (python dan.py \320\267\320\260\320\274\320\265\321\200\320\270\321\202\321\214 \320\277\321\200\320\276\320\263\321\200\320\260\320\274\320\274\320\260.dan) ----\n   A benchmark runs in batches: the batch grows until it takes at least 20 ms,\n   then 10 batches are timed. The temporaries of every run are freed after it.\n   For each benchmark one line goes to the file named by the DAN_BENCH\n   environment variable (or to the standard output): name, mean time of one\n   run, standard deviation and minimum in nanoseconds, number of runs; after a\n   runtime error - name, \"!\", message, file and line. */\n\nstatic FILE *dan_bench_out;\n\nstatic uint64_t dan_bench_now(void) {\n#ifdef _WIN32\n    static LARGE_INTEGER freq;\n    LARGE_INTEGER c;\n    if (!freq.QuadPart) QueryPerformanceFrequency(&freq);\n    QueryPerformanceCounter(&c);\n    return (uint64_t)(c.QuadPart / freq.QuadPart) * 1000000000u\n         + (uint64_t)(c.QuadPart % freq.QuadPart) * 1000000000u / (uint64_t)freq.QuadPart;\n#else\n    struct timespec t;\n    clock_gettime(CLOCK_MONOTONIC, &t);\n    return (uint64_t)t.tv_sec * 1000000000u + (uint64_t)t.tv_nsec;\n#endif\n}\n\nstatic void dan_bench_open(void) {\n#ifdef _WIN32\n    const wchar_t *path = _wgetenv(L\"DAN_BENCH\");\n    dan_bench_out = path && *path \? _wfopen(path, L\"wb\") : NULL;\n#else\n    const char *path = getenv(\"DAN_BENCH\");\n    dan_bench_out = path && *path \? fopen(path, \"wb\") : NULL;\n#endif\n    if (!dan_bench_out) dan_bench_out = stdout;\n}\n\nstatic double dan_bench_batch(void (*f)(void), uint64_t n) {\n    uint64_t start = dan_bench_now();\n    for (uint64_t i = 0; i < n; i++) {\n        const size_t m = dan_mark();\n        f();\n        dan_sweep(m);\n    }\n    return (double)(dan_bench_now() - start);\n}\n\nstatic void dan_bench(const char *name, void (*f)(void)) {\n#ifndef __wasi__\n    jmp_buf here;\n    if (setjmp(here)) {\n        dan_catch = NULL;\n        int l = dan_caught_line;\n        int file = l >= DAN_FILE_STEP && l / DAN_FILE_STEP < DAN_FILE_COUNT \? l / DAN_FILE_STEP : 0;\n        fprintf(dan_bench_out, \"%s\\t!\\t%s\\t%s\\t%d\\n\", name, dan_caught, dan_files[file], l % DAN_FILE_STEP);\n        fflush(dan_bench_out);\n        return;\n    }\n    dan_catch = &here;\n#endif\n    uint64_t n = 1;\n    dan_bench_batch(f, 1);                       /* warm-up */\n    for (;;) {\n        double t = dan_bench_batch(f, n);\n        if (t >= 20e6 || n >= ((uint64_t)1 << 40)) break;\n        uint64_t next = t > 0 \? (uint64_t)((double)n * 25e6 / t) + 1 : n * 10;\n        n = next > n * 2 \? next : n * 2;\n        if (n > ((uint64_t)1 << 40)) n = (uint64_t)1 << 40;\n    }\n    double s[10], sum = 0, sq = 0, low = 0;\n    for (int k = 0; k < 10; k++) {\n        s[k] = dan_bench_batch(f, n) / (double)n;\n        sum += s[k];\n        if (k == 0 || s[k] < low) low = s[k];\n    }\n    double mean = sum / 10;\n    for (int k = 0; k < 10; k++) sq += (s[k] - mean) * (s[k] - mean);\n#ifndef __wasi__\n    dan_catch = NULL;\n#endif\n    fprintf(dan_bench_out, \"%s\\t%.6g\\t%.6g\\t%.6g\\t%\" PRIu64 \"\\n\", name, mean, sqrt(sq / 9), low, n * 10);\n    fflush(dan_bench_out);\n}\n");
DAN_STATIC_STR(dan_lit_2146, "\n/* ---- debugger (python dan.py \320\276\321\202\320\273\320\260\320\264\320\272\320\260 \320\277\321\200\320\276\320\263\321\200\320\260\320\274\320\274\320\260.dan) ----\n   Every statement calls dan_dbg_line; functions and variables register\n   themselves in the tables below and leave them automatically at the end\n   of their C scope (the cleanup attribute), so the debugger always knows\n   which variables exist at the current line. Only the main thread is\n   debugged; tasks run without stops. */\n\ntypedef struct { const char *name; const void *p; void (*w)(const void *); int frame; } dan_dbg_var_t;\ntypedef struct { const char *name; int line; } dan_dbg_frame_t;\n\nstatic dan_dbg_var_t *dan_dbg_vars;\nstatic int dan_dbg_nvars, dan_dbg_capvars;\nstatic dan_dbg_frame_t *dan_dbg_frames;\nstatic int dan_dbg_depth, dan_dbg_capframes;\nstatic int dan_dbg_mode = 1;               /* 0 - run, 1 - step, 2 - next, 3 - out */\nstatic int dan_dbg_target;\nstatic int *dan_dbg_bps;\nstatic int dan_dbg_nbps;\nstatic DAN_TLS int dan_dbg_main_thread;\nstatic char dan_dbg_last[64] = \"\321\210\320\260\320\263\";\n\nstatic int dan_dbg_enter(const char *name, int line) {\n    if (!dan_dbg_main_thread) return 0;\n    if (dan_dbg_depth == dan_dbg_capframes) {\n        dan_dbg_capframes = dan_dbg_capframes \? dan_dbg_capframes * 2 : 64;\n        dan_dbg_frames = dan_realloc(dan_dbg_frames, sizeof *dan_dbg_frames * (size_t)dan_dbg_capframes);\n    }\n    dan_dbg_frames[dan_dbg_depth].name = name;\n    dan_dbg_frames[dan_dbg_depth].line = line;\n    return ++dan_dbg_depth;\n}\n\nstatic void dan_dbg_leave(int *depth) {\n    if (!*depth) return;\n    dan_dbg_depth = *depth - 1;\n    while (dan_dbg_nvars > 0 && dan_dbg_vars[dan_dbg_nvars - 1].frame > dan_dbg_depth) dan_dbg_nvars--;\n}\n\nstatic int dan_dbg_var(const char *name, const void *p, void (*w)(const void *)) {\n    if (!dan_dbg_main_thread) return 0;\n    if (dan_dbg_nvars == dan_dbg_capvars) {\n        dan_dbg_capvars = dan_dbg_capvars \? dan_dbg_capvars * 2 : 256;\n        dan_dbg_vars = dan_realloc(dan_dbg_vars, sizeof *dan_dbg_vars * (size_t)dan_dbg_capvars);\n    }\n    dan_dbg_var_t *v = &dan_dbg_vars[dan_dbg_nvars++];\n    v->name = name;\n    v->p = p;\n    v->w = w;\n    v->frame = dan_dbg_depth;\n    return dan_dbg_nvars;\n}\n\nstatic void dan_dbg_unvar(int *n) {\n    if (*n && dan_dbg_nvars >= *n) dan_dbg_nvars = *n - 1;\n}\n\nstatic void dan_dbg_where(int line) {\n    int file = line / DAN_FILE_STEP, n = line % DAN_FILE_STEP;\n    printf(\"%s:%d\", file < DAN_FILE_COUNT \? dan_files[file] : \"\?\", n);\n}\n\nstatic void dan_dbg_show_source(int line, int around) {\n    int file = line / DAN_FILE_STEP, n = line % DAN_FILE_STEP;\n    if (file >= DAN_FILE_COUNT) return;\n    for (int i = n - around; i <= n + around; i++) {\n        if (i < 1 || i > dan_dbg_src_count[file]) continue;\n        printf(\"%s%5d  %s\\n\", i == n \? \"->\" : \"  \", i, dan_dbg_src[file][i - 1]);\n    }\n}\n\nstatic void dan_dbg_show_vars(const char *only) {\n    int shown = 0;\n    for (int i = 0; i < dan_dbg_nvars; i++) {\n        dan_dbg_var_t *v = &dan_dbg_vars[i];\n        if (v->frame != dan_dbg_depth) continue;\n        if (only && strcmp(only, v->name) != 0) continue;\n        /* an inner variable with the same name hides the outer one */\n        int hidden = 0;\n        for (int j = i + 1; j < dan_dbg_nvars; j++)\n            if (dan_dbg_vars[j].frame == dan_dbg_depth && strcmp(dan_dbg_vars[j].name, v->name) == 0) hidden = 1;\n        if (hidden) continue;\n        printf(\"  %s = \", v->name);\n        v->w(v->p);\n        putchar('\\n');\n        shown++;\n    }\n    if (!shown) puts(only \? DAN_TXT_DBG_NO_VAR : DAN_TXT_DBG_NO_VARS);\n}\n\nstatic void dan_dbg_show_stack(void) {\n    for (int i = dan_dbg_depth - 1; i >= 0; i--) {\n        printf(\"  %s, \", dan_dbg_frames[i].name);\n        dan_dbg_where(dan_dbg_frames[i].line);\n        putchar('\\n');\n    }\n}\n\n/* a line of input; -1 when the input has ended */\nstatic int dan_dbg_read(char *buf, size_t size) {\n    fflush(stdout);\n#ifdef _WIN32\n    HANDLE h = GetStdHandle(STD_INPUT_HANDLE);\n    DWORD mode;\n    if (GetConsoleMode(h, &mode)) {\n        wchar_t w[256];\n        size_t len = 0;\n");
DAN_STATIC_STR(dan_lit_2147, "        for (;;) {\n            DWORD got = 0;\n            wchar_t c;\n            if (!ReadConsoleW(h, &c, 1, &got, NULL) || got == 0) { if (!len) return -1; break; }\n            if (c == L'\\n') break;\n            if (c != L'\\r' && len < 255) w[len++] = c;\n        }\n        int n = WideCharToMultiByte(CP_UTF8, 0, w, (int)len, buf, (int)size - 1, NULL, NULL);\n        buf[n > 0 \? n : 0] = 0;\n        return 0;\n    }\n#endif\n    if (!fgets(buf, (int)size, stdin)) return -1;\n    size_t n = strlen(buf);\n    while (n > 0 && (buf[n - 1] == '\\n' || buf[n - 1] == '\\r')) buf[--n] = 0;\n    return 0;\n}\n\nstatic int dan_dbg_is(const char *cmd, const char *full, const char *short_) {\n    return strcmp(cmd, full) == 0 || strcmp(cmd, short_) == 0;\n}\n\n/* the dialogue at a stop; \302\253error\302\273 - the program stops because of an error */\nstatic void dan_dbg_prompt(int line, int error) {\n    for (;;) {\n        printf(DAN_TXT_DBG_PROMPT);\n        char buf[256];\n        if (dan_dbg_read(buf, sizeof buf) < 0) {\n            dan_dbg_mode = 0;          /* no more commands: the program runs to the end */\n            dan_dbg_nbps = 0;\n            return;\n        }\n        char *cmd = buf;\n        while (*cmd == ' ') cmd++;\n        if (!*cmd) cmd = dan_dbg_last;\n        else snprintf(dan_dbg_last, sizeof dan_dbg_last, \"%s\", cmd);\n        char *arg = strchr(cmd, ' ');\n        if (arg) { *arg++ = 0; while (*arg == ' ') arg++; if (!*arg) arg = NULL; }\n        if (dan_dbg_is(cmd, \"\321\210\320\260\320\263\", \"\321\210\")) { if (error) { puts(DAN_TXT_DBG_AFTER_ERROR); continue; } dan_dbg_mode = 1; return; }\n        if (dan_dbg_is(cmd, \"\320\264\320\260\320\273\320\265\320\265\", \"\320\264\")) { if (error) { puts(DAN_TXT_DBG_AFTER_ERROR); continue; } dan_dbg_mode = 2; dan_dbg_target = dan_dbg_depth; return; }\n        if (dan_dbg_is(cmd, \"\320\262\321\213\320\271\321\202\320\270_\320\270\320\267\", \"\320\262\321\213\")) { if (error) { puts(DAN_TXT_DBG_AFTER_ERROR); continue; } dan_dbg_mode = 3; dan_dbg_target = dan_dbg_depth; return; }\n        if (dan_dbg_is(cmd, \"\320\277\321\200\320\276\320\264\320\276\320\273\320\266\320\270\321\202\321\214\", \"\320\277\")) { dan_dbg_mode = 0; return; }\n        if (dan_dbg_is(cmd, \"\321\201\321\202\320\276\320\277\", \"\321\201\")) { fflush(stdout); exit(error \? 1 : 0); }\n        if (dan_dbg_is(cmd, \"\320\277\320\276\320\272\320\260\320\267\320\260\321\202\321\214\", \"\320\277\320\272\")) { dan_dbg_show_vars(arg); continue; }\n        if (dan_dbg_is(cmd, \"\321\201\321\202\320\265\320\272\", \"\321\201\321\202\")) { dan_dbg_show_stack(); continue; }\n        if (dan_dbg_is(cmd, \"\321\202\320\265\320\272\321\201\321\202\", \"\321\202\")) { dan_dbg_show_source(line, 5); continue; }\n        if (dan_dbg_is(cmd, \"\321\202\320\276\321\207\320\272\320\260\", \"\321\202\321\207\") || dan_dbg_is(cmd, \"\321\203\320\261\321\200\320\260\321\202\321\214\", \"\321\203\")) {\n            int remove = dan_dbg_is(cmd, \"\321\203\320\261\321\200\320\260\321\202\321\214\", \"\321\203\");\n            if (!arg) {\n                if (!dan_dbg_nbps) puts(DAN_TXT_DBG_NO_BPS);\n                for (int i = 0; i < dan_dbg_nbps; i++) { printf(\"  \"); dan_dbg_where(dan_dbg_bps[i]); putchar('\\n'); }\n                continue;\n            }\n            int file = line / DAN_FILE_STEP;\n            char *colon = strrchr(arg, ':');\n            if (colon) {\n                *colon = 0;\n                file = -1;\n                for (int f = 0; f < DAN_FILE_COUNT; f++) {\n                    const char *name = dan_files[f], *slash = strrchr(name, '/');\n                    if (strcmp(name, arg) == 0 || (slash && strcmp(slash + 1, arg) == 0)) file = f;\n                }\n                arg = colon + 1;\n                if (file < 0) { puts(DAN_TXT_DBG_NO_FILE); continue; }\n            }\n            int n = atoi(arg);\n            if (n <= 0) { puts(DAN_TXT_DBG_BAD_LINE); continue; }\n            int at = file * DAN_FILE_STEP + n;\n            if (remove) {\n                int k = 0;\n                for (int i = 0; i < dan_dbg_nbps; i++) if (dan_dbg_bps[i] != at) dan_dbg_bps[k++] = dan_dbg_bps[i];\n                dan_dbg_nbps = k;\n            } else {\n                dan_dbg_bps = dan_realloc(dan_dbg_bps, sizeof(int) * (size_t)(dan_dbg_nbps + 1));\n                dan_dbg_bps[dan_dbg_nbps++] = at;\n                printf(DAN_TXT_DBG_BP_SET);\n                dan_dbg_where(at);\n                putchar('\\n');\n            }\n            continue;\n        }\n        puts(DAN_TXT_DBG_HELP);\n    }\n}\n\nstatic void dan_dbg_line(int line) {\n");
DAN_STATIC_STR(dan_lit_2148, "    if (!dan_dbg_main_thread) return;\n    if (dan_dbg_depth > 0) dan_dbg_frames[dan_dbg_depth - 1].line = line;\n    int stop = dan_dbg_mode == 1 || (dan_dbg_mode == 2 && dan_dbg_depth <= dan_dbg_target)\n               || (dan_dbg_mode == 3 && dan_dbg_depth < dan_dbg_target);\n    for (int i = 0; !stop && i < dan_dbg_nbps; i++) stop = dan_dbg_bps[i] == line;\n    if (!stop) return;\n    fflush(stdout);\n    printf(\"\\n\");\n    dan_dbg_where(line);\n    printf(\" (%s)\\n\", dan_dbg_depth > 0 \? dan_dbg_frames[dan_dbg_depth - 1].name : \"\");\n    dan_dbg_show_source(line, 0);\n    dan_dbg_prompt(line, 0);\n}\n\nstatic void dan_dbg_error(const char *text, int line) {\n    if (!dan_dbg_main_thread) return;\n    fflush(stdout);\n    printf(\"\\n\" DAN_TXT_DBG_ERROR, text);\n    if (line > 0) { dan_dbg_where(line); putchar('\\n'); dan_dbg_show_source(line, 0); }\n    dan_dbg_prompt(line, 1);\n}\n\nstatic void dan_dbg_start(void) {\n    dan_dbg_main_thread = 1;\n    puts(DAN_TXT_DBG_HELLO);\n}\n");
DAN_STATIC_STR(dan_lit_2149, "\n/* ---- calendar dates (\320\264\320\260\321\202\320\260): days since 01.01.1970, Gregorian calendar ---- */\ntypedef struct { int64_t d; } dan_date;\n\nstatic int64_t dan_days_from_civil(int64_t y, int64_t m, int64_t d) {\n    y -= m <= 2;\n    int64_t era = (y >= 0 \? y : y - 399) / 400;\n    int64_t yoe = y - era * 400;\n    int64_t doy = (153 * (m + (m > 2 \? -3 : 9)) + 2) / 5 + d - 1;\n    int64_t doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;\n    return era * 146097 + doe - 719468;\n}\nstatic void dan_civil_from_days(int64_t z, int64_t *y, int64_t *m, int64_t *d) {\n    z += 719468;\n    int64_t era = (z >= 0 \? z : z - 146096) / 146097;\n    int64_t doe = z - era * 146097;\n    int64_t yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;\n    int64_t doy = doe - (365 * yoe + yoe / 4 - yoe / 100);\n    int64_t mp = (5 * doy + 2) / 153;\n    *d = doy - (153 * mp + 2) / 5 + 1;\n    *m = mp < 10 \? mp + 3 : mp - 9;\n    *y = yoe + era * 400 + (*m <= 2);\n}\nstatic int64_t dan_days_in_month(int64_t y, int64_t m, int line) {\n    static const int t[] = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };\n    if (m < 1 || m > 12) dan_error(DAN_MSG_BAD_MONTH, line);\n    return m == 2 && ((y % 4 == 0 && y % 100 != 0) || y % 400 == 0) \? 29 : t[m - 1];\n}\n#define DAN_DATE_MIN (-719162)    /* 01.01.0001 */\n#define DAN_DATE_MAX 2932896      /* 31.12.9999 */\nstatic dan_date dan_date_check(int64_t d, int line) {\n    if (d < DAN_DATE_MIN || d > DAN_DATE_MAX) dan_error(DAN_MSG_DATE_RANGE, line);\n    dan_date r = { d };\n    return r;\n}\nstatic dan_date dan_date_make(int64_t y, int64_t m, int64_t d, int line) {\n    if (y < 1 || y > 9999 || m < 1 || m > 12 || d < 1 || d > dan_days_in_month(y, m, line)) {\n        char b[160];\n        snprintf(b, sizeof b, DAN_MSG_NO_DATE, (long long)d, (long long)m, (long long)y);\n        dan_error(b, line);\n    }\n    dan_date r = { dan_days_from_civil(y, m, d) };\n    return r;\n}\n/* \302\25326.10.2026\302\273, \302\2536.1.2026\302\273 or \302\2532026-10-26\302\273; 0 if the text is not a date */\nstatic int dan_date_scan(dan_str s, int64_t *y, int64_t *m, int64_t *d) {\n    const char *p = s;\n    int64_t n[3] = { 0, 0, 0 };\n    int digits[3] = { 0, 0, 0 }, k = 0;\n    char sep = 0;\n    while (*p == ' ') p++;\n    for (; *p && *p != ' '; p++) {\n        if (*p >= '0' && *p <= '9') {\n            if (digits[k] >= 4) return 0;\n            n[k] = n[k] * 10 + (*p - '0');\n            digits[k]++;\n        } else if ((*p == '.' || *p == '-' || *p == '/') && k < 2 && digits[k] && (!sep || sep == *p)) {\n            sep = *p;\n            k++;\n        } else {\n            return 0;\n        }\n    }\n    while (*p == ' ') p++;\n    if (*p || k != 2 || !digits[2]) return 0;\n    if (sep == '-' && digits[0] == 4) { *y = n[0]; *m = n[1]; *d = n[2]; return 1; }\n    if (sep != '-' && digits[2] == 4 && digits[0] <= 2 && digits[1] <= 2) { *d = n[0]; *m = n[1]; *y = n[2]; return 1; }\n    return 0;\n}\nstatic int dan_date_valid(int64_t y, int64_t m, int64_t d) {\n    if (y < 1 || y > 9999 || m < 1 || m > 12 || d < 1) return 0;\n    return d <= dan_days_in_month(y, m, 0);\n}\nstatic dan_date dan_date_from_str(dan_str s, int line) {\n    int64_t y, m, d;\n    if (!dan_date_scan(s, &y, &m, &d)) dan_conv_error(DAN_MSG_NOT_DATE, s, line);\n    return dan_date_make(y, m, d, line);\n}\nstatic dan_str dan_date_to_str(dan_date v) {\n    int64_t y, m, d;\n    char b[32];\n    dan_civil_from_days(v.d, &y, &m, &d);\n    snprintf(b, sizeof b, \"%02d.%02d.%04d\", (int)d, (int)m, (int)y);\n    return dan_strdup(b);\n}\nstatic void dan_write_date(dan_date v) {\n    int64_t y, m, d;\n    dan_civil_from_days(v.d, &y, &m, &d);\n    printf(\"%02d.%02d.%04d\", (int)d, (int)m, (int)y);\n}\nstatic dan_date dan_date_add(dan_date a, int64_t n, int line) {\n    int64_t r;\n    if (__builtin_add_overflow(a.d, n, &r)) dan_error(DAN_MSG_DATE_RANGE, line);\n    return dan_date_check(r, line);\n}\nstatic dan_date dan_date_sub_days(dan_date a, int64_t n, int line) {\n    int64_t r;\n    if (__builtin_sub_overflow(a.d, n, &r)) dan_error(DAN_MSG_DATE_RANGE, line);\n");
DAN_STATIC_STR(dan_lit_2150, "    return dan_date_check(r, line);\n}\nstatic int64_t dan_date_diff(dan_date a, dan_date b) { return a.d - b.d; }\nstatic int dan_date_cmp(dan_date a, dan_date b) { return a.d < b.d \? -1 : a.d > b.d; }\nstatic bool dan_date_eq(dan_date a, dan_date b) { return a.d == b.d; }\nstatic int64_t dan_date_year(dan_date v) { int64_t y, m, d; dan_civil_from_days(v.d, &y, &m, &d); return y; }\nstatic int64_t dan_date_month(dan_date v) { int64_t y, m, d; dan_civil_from_days(v.d, &y, &m, &d); return m; }\nstatic int64_t dan_date_day(dan_date v) { int64_t y, m, d; dan_civil_from_days(v.d, &y, &m, &d); return d; }\n/* 1 - \320\277\320\276\320\275\320\265\320\264\320\265\320\273\321\214\320\275\320\270\320\272, 7 - \320\262\320\276\321\201\320\272\321\200\320\265\321\201\320\265\320\275\321\214\320\265 (01.01.1970 - \321\207\320\265\321\202\320\262\320\265\321\200\320\263) */\nstatic int64_t dan_date_weekday(dan_date v) { return ((v.d % 7) + 7 + 3) % 7 + 1; }\nstatic int64_t dan_date_yday(dan_date v) { return v.d - dan_days_from_civil(dan_date_year(v), 1, 1) + 1; }\n");
DAN_STATIC_STR(dan_lit_2151, "\n/* ---- complex numbers (\320\272\320\276\320\274\320\277\320\273) ---- */\ntypedef struct { double re, im; } dan_cx;\nstatic inline dan_cx dan_cx_make(double re, double im) { dan_cx z; z.re = re; z.im = im; return z; }\nstatic inline dan_cx dan_cx_add(dan_cx a, dan_cx b, int line) { (void)line; return dan_cx_make(a.re + b.re, a.im + b.im); }\nstatic inline dan_cx dan_cx_sub(dan_cx a, dan_cx b, int line) { (void)line; return dan_cx_make(a.re - b.re, a.im - b.im); }\nstatic inline dan_cx dan_cx_mul(dan_cx a, dan_cx b, int line) {\n    (void)line;\n    return dan_cx_make(a.re * b.re - a.im * b.im, a.re * b.im + a.im * b.re);\n}\n/* division without overflow of intermediate products (Smith's method) */\nstatic dan_cx dan_cx_div(dan_cx a, dan_cx b, int line) {\n    if (b.re == 0 && b.im == 0) dan_error(DAN_MSG_DIV_ZERO, line);\n    if (fabs(b.re) >= fabs(b.im)) {\n        double r = b.im / b.re, d = b.re + b.im * r;\n        return dan_cx_make((a.re + a.im * r) / d, (a.im - a.re * r) / d);\n    }\n    double r = b.re / b.im, d = b.re * r + b.im;\n    return dan_cx_make((a.re * r + a.im) / d, (a.im * r - a.re) / d);\n}\nstatic inline dan_cx dan_cx_neg(dan_cx a) { return dan_cx_make(-a.re, -a.im); }\nstatic inline bool dan_cx_eq(dan_cx a, dan_cx b) { return a.re == b.re && a.im == b.im; }\nstatic inline double dan_cx_abs(dan_cx a) { return hypot(a.re, a.im); }\nstatic inline double dan_cx_arg(dan_cx a) { return atan2(a.im, a.re); }\nstatic inline dan_cx dan_cx_conj(dan_cx a) { return dan_cx_make(a.re, -a.im); }\nstatic dan_cx dan_cx_exp(dan_cx a) { double e = exp(a.re); return dan_cx_make(e * cos(a.im), e * sin(a.im)); }\nstatic dan_cx dan_cx_ln(dan_cx a, int line) {\n    if (a.re == 0 && a.im == 0) dan_error(DAN_MSG_CX_LOG_ZERO, line);\n    return dan_cx_make(log(dan_cx_abs(a)), dan_cx_arg(a));\n}\n/* principal square root: the real part is never negative */\nstatic dan_cx dan_cx_sqrt(dan_cx a) {\n    if (a.re == 0 && a.im == 0) return a;\n    double m = dan_cx_abs(a);\n    double re = sqrt((m + fabs(a.re)) / 2);\n    if (a.re >= 0) return dan_cx_make(re, a.im / (2 * re));\n    double im = a.im < 0 \? -re : re;\n    return dan_cx_make(fabs(a.im) / (2 * re), im);\n}\n/* whole powers are computed by multiplication, so (1 + i)^2 is exactly 2i */\nstatic dan_cx dan_cx_pow_int(dan_cx a, int64_t e, int line) {\n    if (e < 0) {\n        if (a.re == 0 && a.im == 0) dan_error(DAN_MSG_DIV_ZERO, line);\n        return dan_cx_div(dan_cx_make(1, 0), dan_cx_pow_int(a, e == INT64_MIN \? INT64_MAX : -e, line), line);\n    }\n    dan_cx r = dan_cx_make(1, 0);\n    while (e > 0) {\n        if (e & 1) r = dan_cx_mul(r, a, line);\n        e >>= 1;\n        if (e) a = dan_cx_mul(a, a, line);\n    }\n    return r;\n}\nstatic dan_cx dan_cx_pow(dan_cx a, dan_cx b, int line) {\n    if (b.im == 0 && b.re == floor(b.re) && fabs(b.re) < 9e18) return dan_cx_pow_int(a, (int64_t)b.re, line);\n    if (a.re == 0 && a.im == 0) {\n        if (b.re > 0) return a;\n        dan_error(DAN_MSG_DIV_ZERO, line);\n    }\n    return dan_cx_exp(dan_cx_mul(b, dan_cx_ln(a, line), line));\n}\n\nstatic void dan_cx_part(char *buf, size_t size, double v) {\n    dan_format_float(buf, size, v);\n    size_t n = strlen(buf);\n    if (n > 2 && buf[n - 2] == '.' && buf[n - 1] == '0') buf[n - 2] = 0;    /* 3.0 -> 3 */\n}\n/* written as in mathematics: 3 + 4i, 2 - i, 5i, -1 */\nstatic dan_str dan_cx_to_str(dan_cx a) {\n    char re[64], im[64], out[160];\n    double ai = a.im;\n    dan_cx_part(re, sizeof re, a.re);\n    dan_cx_part(im, sizeof im, fabs(ai));\n    const char *imp = strcmp(im, \"1\") == 0 \? \"\" : im;\n    if (ai == 0) snprintf(out, sizeof out, \"%s\", re);\n    else if (a.re == 0) snprintf(out, sizeof out, \"%s%si\", ai < 0 \? \"-\" : \"\", imp);\n    else snprintf(out, sizeof out, \"%s %s %si\", re, ai < 0 \? \"-\" : \"+\", imp);\n    return dan_strdup(out);\n}\nstatic void dan_write_cx(dan_cx a) { fputs(dan_cx_to_str(a), stdout); }\nstatic dan_cx dan_cx_from_str(dan_str s, int line) {\n    char *end;\n    double v = strtod(s, &end);\n    if (end == s) dan_conv_error(DAN_MSG_NOT_FLOAT, s, line);\n");
DAN_STATIC_STR(dan_lit_2152, "    return dan_cx_make(v, 0);\n}\n");
DAN_STATIC_STR(dan_lit_2153, "\nstatic dl_Lc *dan_cx_quadratic(double a, double b, double c) {\n    dl_Lc *r = dl_Lc_from(0, NULL);\n    if (a == 0) {\n        if (b != 0) dl_Lc_push(r, dan_cx_make(-c / b, 0));\n        return r;\n    }\n    double d = b * b - 4 * a * c;\n    if (d >= 0) {\n        double s = sqrt(d);\n        dl_Lc_push(r, dan_cx_make((-b + s) / (2 * a), 0));\n        if (d > 0) dl_Lc_push(r, dan_cx_make((-b - s) / (2 * a), 0));\n    } else {\n        double s = sqrt(-d);\n        dl_Lc_push(r, dan_cx_make(-b / (2 * a), s / (2 * a)));\n        dl_Lc_push(r, dan_cx_make(-b / (2 * a), -s / (2 * a)));\n    }\n    return r;\n}\n");
DAN_STATIC_STR(dan_lit_2154, "\n/* ---- tasks and channels ---- */\n#define DAN_TASK_STACK ((size_t)64 * 1024 * 1024)\n#ifdef _WIN32\ntypedef HANDLE dan_thread_t;\ntypedef CRITICAL_SECTION dan_mutex_t;\ntypedef CONDITION_VARIABLE dan_cond_t;\n#define DAN_THREAD_FN DWORD WINAPI\n#define DAN_THREAD_RETURN 0\nstatic void dan_mutex_init(dan_mutex_t *m) { InitializeCriticalSection(m); }\nstatic void dan_lock(dan_mutex_t *m) { EnterCriticalSection(m); }\nstatic void dan_unlock(dan_mutex_t *m) { LeaveCriticalSection(m); }\nstatic void dan_cond_init(dan_cond_t *c) { InitializeConditionVariable(c); }\nstatic void dan_cond_wait(dan_cond_t *c, dan_mutex_t *m) { SleepConditionVariableCS(c, m, INFINITE); }\nstatic void dan_cond_signal(dan_cond_t *c) { WakeConditionVariable(c); }\nstatic void dan_cond_free(dan_cond_t *c) { (void)c; }\nstatic int dan_thread_create(dan_thread_t *t, DWORD (WINAPI *f)(void *), void *a) {\n    *t = CreateThread(NULL, DAN_TASK_STACK, f, a, STACK_SIZE_PARAM_IS_A_RESERVATION, NULL);\n    return *t != NULL;\n}\nstatic void dan_thread_join(dan_thread_t t) { WaitForSingleObject(t, INFINITE); CloseHandle(t); }\n#else\ntypedef pthread_t dan_thread_t;\ntypedef pthread_mutex_t dan_mutex_t;\ntypedef pthread_cond_t dan_cond_t;\n#define DAN_THREAD_FN void *\n#define DAN_THREAD_RETURN NULL\nstatic void dan_mutex_init(dan_mutex_t *m) { pthread_mutex_init(m, NULL); }\nstatic void dan_lock(dan_mutex_t *m) { pthread_mutex_lock(m); }\nstatic void dan_unlock(dan_mutex_t *m) { pthread_mutex_unlock(m); }\nstatic void dan_cond_init(dan_cond_t *c) { pthread_cond_init(c, NULL); }\nstatic void dan_cond_wait(dan_cond_t *c, dan_mutex_t *m) { pthread_cond_wait(c, m); }\nstatic void dan_cond_signal(dan_cond_t *c) { pthread_cond_signal(c); }\nstatic void dan_cond_free(dan_cond_t *c) { pthread_cond_destroy(c); }\nstatic int dan_thread_create(dan_thread_t *t, void *(*f)(void *), void *a) {\n    pthread_attr_t at;\n    pthread_attr_init(&at);\n    pthread_attr_setstacksize(&at, DAN_TASK_STACK);\n    int ok = pthread_create(t, &at, f, a) == 0;\n    pthread_attr_destroy(&at);\n    return ok;\n}\nstatic void dan_thread_join(dan_thread_t t) { pthread_join(t, NULL); }\n#endif\n\n/* Every task (and the main program) has a record. All waiting happens under\n   one lock, and the number of tasks that are not waiting is counted: when it\n   drops to zero, no task can ever wake the others, and the program stops\n   with a list of where each task waits (instead of hanging silently). */\ntypedef struct dan_trec {\n    dan_cond_t cond;\n    int blocked, line, start_line, is_main;\n    const char *what;\n    struct dan_trec *next_all, *prev_all, *next_wait;\n} dan_trec;\nstatic dan_mutex_t dan_sched, dan_out_mx;\nstatic dan_trec *dan_all, dan_main_rec;\nstatic int dan_active;\nstatic DAN_TLS dan_trec *dan_self;\n\nstatic dan_mutex_t dan_fail_mx;\nstatic void dan_fail_once(void) { dan_lock(&dan_fail_mx); }   /* never released: the program is ending */\nstatic void dan_out_lock(void) { dan_lock(&dan_out_mx); }\nstatic void dan_out_unlock(void) { dan_unlock(&dan_out_mx); }\n\nstatic void dan_trec_add(dan_trec *t) {\n    t->prev_all = NULL; t->next_all = dan_all;\n    if (dan_all) dan_all->prev_all = t;\n    dan_all = t;\n}\nstatic void dan_trec_remove(dan_trec *t) {\n    if (t->prev_all) t->prev_all->next_all = t->next_all; else dan_all = t->next_all;\n    if (t->next_all) t->next_all->prev_all = t->prev_all;\n}\n\nstatic void dan_print_place(const char *what, int line) {\n    if (line >= DAN_FILE_STEP && line / DAN_FILE_STEP < DAN_FILE_COUNT)\n        fprintf(stderr, DAN_TXT_AT_FILE_LINE, what, dan_files[line / DAN_FILE_STEP], line % DAN_FILE_STEP);\n    else\n        fprintf(stderr, DAN_TXT_AT_LINE, what, line);\n}\n\nstatic void dan_deadlock(void) {\n    dan_fail_once();\n    fflush(stdout);\n    fputs(DAN_MSG_DEADLOCK, stderr);\n    for (dan_trec *t = dan_all; t; t = t->next_all) {\n        if (!t->blocked) continue;\n        if (t->is_main) fputs(DAN_TXT_MAIN_WAITS, stderr);\n        else fprintf(stderr, DAN_TXT_TASK_WAITS, t->start_line % DAN_FILE_STEP);\n");
DAN_STATIC_STR(dan_lit_2155, "        dan_print_place(t->what, t->line);\n    }\n    exit(1);\n}\n\n/* called under dan_sched: wait until a waker clears \302\253blocked\302\273 */\nstatic void dan_block(dan_trec **list, int line, const char *what) {\n    dan_trec *me = dan_self;\n    me->blocked = 1; me->line = line; me->what = what;\n    me->next_wait = *list; *list = me;\n    if (--dan_active == 0) dan_deadlock();\n    while (me->blocked) dan_cond_wait(&me->cond, &dan_sched);\n}\nstatic void dan_wake_all(dan_trec **list) {\n    for (dan_trec *t = *list; t; t = t->next_wait) {\n        if (t->blocked) { t->blocked = 0; dan_active++; dan_cond_signal(&t->cond); }\n    }\n    *list = NULL;\n}\n\nstatic void dan_tasks_init(void) {\n    dan_mutex_init(&dan_fail_mx);\n    dan_on_error = dan_fail_once;\n    dan_mutex_init(&dan_sched);\n    dan_mutex_init(&dan_out_mx);\n    dan_cond_init(&dan_main_rec.cond);\n    dan_main_rec.is_main = 1;\n    dan_trec_add(&dan_main_rec);\n    dan_self = &dan_main_rec;\n    dan_active = 1;\n}\n\ntypedef struct dan_task {\n    dan_thread_t th;\n    int done, joined, line;\n    dan_trec *joiners;\n    dan_trec rec;\n    struct dan_task *next;\n} dan_task;\n\nstatic void dan_task_start(dan_task *t, DAN_THREAD_FN (*f)(void *), void *arg, int line) {\n    t->done = 0; t->joined = 0; t->line = line; t->joiners = NULL; t->next = NULL;\n    memset(&t->rec, 0, sizeof t->rec);\n    dan_cond_init(&t->rec.cond);\n    t->rec.start_line = line;\n    dan_lock(&dan_sched);\n    dan_trec_add(&t->rec);\n    dan_active++;\n    dan_unlock(&dan_sched);\n    if (!dan_thread_create(&t->th, f, arg)) dan_error(DAN_MSG_THREAD, line);\n}\n\n/* the beginning of the task's own thread */\nstatic void dan_task_begin(dan_task *t) {\n    char here;\n    dan_self = &t->rec;\n    dan_stack_base = (uintptr_t)&here;\n    dan_stack_limit = DAN_TASK_STACK / 4 * 3;\n}\n\nstatic void dan_task_end(dan_task *t) {\n    dan_free(dan_zct); dan_free(dan_dead);\n    dan_zct = dan_dead = NULL;\n    dan_zct_n = dan_zct_cap = dan_dead_n = dan_dead_cap = 0;\n    dan_lock(&dan_sched);\n    dan_trec_remove(&t->rec);\n    t->done = 1;\n    dan_wake_all(&t->joiners);\n    if (--dan_active == 0 && dan_all) dan_deadlock();\n    dan_unlock(&dan_sched);\n}\n\nstatic void dan_task_join(dan_task *t, int line) {\n    dan_lock(&dan_sched);\n    while (!t->done) dan_block(&t->joiners, line, DAN_TXT_WAIT_TASK);\n    dan_unlock(&dan_sched);\n    if (!t->joined) {\n        dan_thread_join(t->th);\n        dan_cond_free(&t->rec.cond);\n        t->joined = 1;\n    }\n}\n\nstatic bool dan_task_ready(dan_task *t) {\n    dan_lock(&dan_sched);\n    bool r = t->done != 0;\n    dan_unlock(&dan_sched);\n    return r;\n}\n\n/* \302\253\320\277\320\260\321\200\320\260\320\273\320\273\320\265\320\273\321\214\320\275\320\276 { ... }\302\273: tasks without a name belong to the block */\ntypedef struct { dan_task *head; } dan_tgroup;\nstatic void dan_tgroup_add(dan_tgroup *g, dan_task *t) { t->next = g->head; g->head = t; }\nstatic void dan_tgroup_join(dan_tgroup *g, int line) {\n    while (g->head) {\n        dan_task *t = g->head;\n        g->head = t->next;\n        dan_task_join(t, line);\n        dan_free(t);\n    }\n}\n\n/* Channels. Values in a channel are copies made for the receiver. An\n   unbuffered channel (capacity 0) makes the sender wait until the value is\n   taken. Receiving from a closed channel gives the remaining values, then\n   \302\253\320\275\320\270\321\207\320\265\320\263\320\276\302\273; sending to a closed channel is an error. */\ntypedef struct dan_chan {\n    dan_hdr h;\n    size_t esize;\n    int64_t slots, head, count, sent, taken;\n    int closed, unbuffered;\n    unsigned char *buf;\n    void (*drop)(void *);\n    dan_trec *waiters;\n} dan_chan;\n\nstatic void dan_chan_destroy(dan_hdr *h) {\n    dan_chan *c = (dan_chan *)(void *)h;\n    for (int64_t i = 0; i < c->count; i++) c->drop(c->buf + (size_t)((c->head + i) % c->slots) * c->esize);\n    dan_free(c->buf);\n    dan_free(c);\n}\n/* the table of temporaries reached a channel: decide under the lock */\nstatic void dan_chan_zct_done(dan_hdr *h) {\n    dan_lock(&dan_sched);\n    h->flags &= (uint16_t)~DAN_IN_ZCT;\n    int dead = h->rc == 0;\n    dan_unlock(&dan_sched);\n");
DAN_STATIC_STR(dan_lit_2156, "    if (dead) dan_kill(h, dan_chan_destroy);\n}\nstatic dan_chan *dan_chan_new(size_t esize, int64_t cap, void (*drop)(void *), int line) {\n    if (cap < 0) dan_error(DAN_MSG_CHAN_CAP, line);\n    dan_chan *c = dan_alloc(sizeof *c);\n    c->h.rc = 0; c->h.flags = 0; c->h.magic = DAN_MAGIC_SHARED;\n    dan_zct_push(&c->h, dan_chan_zct_done);\n    c->esize = esize;\n    c->unbuffered = cap == 0;\n    c->slots = cap == 0 \? 1 : cap;\n    c->head = c->count = c->sent = c->taken = 0;\n    c->closed = 0;\n    c->buf = dan_alloc((size_t)c->slots * esize);\n    c->drop = drop;\n    c->waiters = NULL;\n    return c;\n}\nstatic dan_chan *dan_chan_share(dan_chan *c) {\n    if (c) { dan_lock(&dan_sched); c->h.rc++; dan_unlock(&dan_sched); }\n    return c;\n}\nstatic void dan_chan_release(dan_chan *c) {\n    if (!c) return;\n    dan_lock(&dan_sched);\n    int dead = --c->h.rc <= 0 && !(c->h.flags & DAN_IN_ZCT);\n    dan_unlock(&dan_sched);\n    if (dead) dan_kill(&c->h, dan_chan_destroy);\n}\nstatic void dan_chan_give(dan_chan *c) {\n    if (!c) return;\n    dan_lock(&dan_sched);\n    if (--c->h.rc <= 0 && !(c->h.flags & DAN_IN_ZCT)) {\n        c->h.rc = 0;\n        c->h.flags |= DAN_IN_ZCT;\n        if (dan_zct_n == dan_zct_cap) {\n            dan_zct_cap = dan_zct_cap \? dan_zct_cap * 2 : 256;\n            dan_zct = dan_realloc(dan_zct, dan_zct_cap * sizeof *dan_zct);\n        }\n        dan_zct[dan_zct_n].h = &c->h;\n        dan_zct[dan_zct_n].d = dan_chan_zct_done;\n        dan_zct_n++;\n    }\n    dan_unlock(&dan_sched);\n}\nstatic dan_chan *dan_chan_clone(dan_chan *c) { return dan_chan_share(c); }\n\nstatic void dan_chan_send(dan_chan *c, const void *v, int line) {\n    dan_lock(&dan_sched);\n    while (!c->closed && c->count == c->slots) dan_block(&c->waiters, line, DAN_TXT_WAIT_SEND);\n    if (c->closed) { dan_unlock(&dan_sched); dan_error(DAN_MSG_SEND_CLOSED, line); }\n    memcpy(c->buf + (size_t)((c->head + c->count) % c->slots) * c->esize, v, c->esize);\n    c->count++;\n    int64_t ticket = ++c->sent;\n    dan_wake_all(&c->waiters);\n    if (c->unbuffered)\n        while (c->taken < ticket) dan_block(&c->waiters, line, DAN_TXT_WAIT_SEND);\n    dan_unlock(&dan_sched);\n}\nstatic int dan_chan_recv(dan_chan *c, void *out, int line) {\n    dan_lock(&dan_sched);\n    while (c->count == 0 && !c->closed) dan_block(&c->waiters, line, DAN_TXT_WAIT_RECV);\n    if (c->count == 0) { dan_unlock(&dan_sched); return 0; }\n    memcpy(out, c->buf + (size_t)c->head * c->esize, c->esize);\n    c->head = (c->head + 1) % c->slots;\n    c->count--;\n    c->taken++;\n    dan_wake_all(&c->waiters);\n    dan_unlock(&dan_sched);\n    return 1;\n}\nstatic void dan_chan_close(dan_chan *c, int line) {\n    dan_lock(&dan_sched);\n    if (c->closed) { dan_unlock(&dan_sched); dan_error(DAN_MSG_CLOSE_TWICE, line); }\n    c->closed = 1;\n    dan_wake_all(&c->waiters);\n    dan_unlock(&dan_sched);\n}\n");
DAN_STATIC_STR(dan_lit_2157, "\n/* ---- list {\320\276\320\277\320\270\321\201\320\260\320\275\320\270\320\265} ---- */\n/* h.rc - \321\207\320\270\321\201\320\273\320\276 \320\274\320\265\321\201\321\202 (\320\277\320\265\321\200\320\265\320\274\320\265\320\275\320\275\321\213\321\205, \320\277\320\276\320\273\320\265\320\271, \321\215\320\273\320\265\320\274\320\265\320\275\321\202\320\276\320\262), \320\263\320\264\320\265 \321\205\321\200\320\260\320\275\320\270\321\202\321\201\321\217 \321\201\320\277\320\270\321\201\320\276\320\272.\n   \320\241\320\277\320\270\321\201\320\276\320\272 - \320\267\320\275\320\260\321\207\320\265\320\275\320\270\320\265: \320\265\321\201\320\273\320\270 \320\274\320\265\321\201\321\202 \320\275\320\265\321\201\320\272\320\276\320\273\321\214\320\272\320\276, \320\277\320\265\321\200\320\265\320\264 \320\270\320\267\320\274\320\265\320\275\320\265\320\275\320\270\320\265\320\274 \320\264\320\265\320\273\320\260\320\265\321\202\321\201\321\217 \320\272\320\276\320\277\320\270\321\217.\n   \320\241\320\277\320\270\321\201\320\276\320\272 \321\201\320\260\320\274 \321\203\321\207\320\270\321\202\321\213\320\262\320\260\320\265\321\202 \321\201\320\262\320\276\320\270 \321\215\320\273\320\265\320\274\320\265\320\275\321\202\321\213: \320\277\321\200\320\270 \320\264\320\276\320\261\320\260\320\262\320\273\320\265\320\275\320\270\320\270 \321\215\320\273\320\265\320\274\320\265\320\275\321\202 \320\277\320\276\320\273\321\203\321\207\320\260\320\265\321\202 \320\265\321\211\321\221\n   \320\276\320\264\320\275\320\276 \320\274\320\265\321\201\321\202\320\276 \321\205\321\200\320\260\320\275\320\265\320\275\320\270\321\217, \320\277\321\200\320\270 \321\203\320\264\320\260\320\273\320\265\320\275\320\270\320\270 - \321\202\320\265\321\200\321\217\320\265\321\202 \320\265\320\263\320\276. */\nstruct {S} {{ dan_hdr h; int64_t len, cap; {T} *items; }};\n\nstatic void {S}_destroy(dan_hdr *h) {{\n    {S} *l = ({S} *)(void *)h;\n    for (int64_t i = 0; i < l->len; i++) {RL}(l->items[i]);\n    dan_free(l->items);\n    dan_free(l);\n}}\n\nstatic {S} *{S}_from(int64_t n, {T} const *src) {{\n    {S} *l = dan_alloc(sizeof *l);\n    dan_hdr_new(&l->h, {S}_destroy);\n    l->len = n;\n    l->cap = n < 4 \? 4 : n;\n    l->items = dan_alloc((size_t)l->cap * sizeof({T}));\n    for (int64_t i = 0; i < n; i++) l->items[i] = {SH}(src[i]);\n    return l;\n}}\n\nstatic void {S}_push({S} *l, {T} v) {{\n    if (l->len == l->cap) {{\n        l->cap *= 2;\n        l->items = dan_realloc(l->items, (size_t)l->cap * sizeof({T}));\n    }}\n    l->items[l->len++] = {SH}(v);\n}}\n\nstatic {T} {S}_get(const {S} *l, int64_t i, int line) {{\n    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);\n    return l->items[i];\n}}\n\nstatic {T} *{S}_at({S} *l, int64_t i, int line) {{\n    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);\n    return &l->items[i];\n}}\n\nstatic void {S}_set({S} *l, int64_t i, {T} v, int line) {{\n    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);\n    {T} old = l->items[i];\n    l->items[i] = {SH}(v);\n    {RL}(old);\n    (void)old;\n}}\n\nstatic void {S}_write(const {S} *l) {{\n    putchar('[');\n    for (int64_t i = 0; i < l->len; i++) {{\n        if (i) fputs(\", \", stdout);\n        {\320\267\320\260\320\277\320\270\321\201\321\214_\321\215\320\273\320\265\320\274\320\265\320\275\321\202\320\260}(l->items[i]);\n    }}\n    putchar(']');\n}}\n\nstatic void {S}_insert({S} *l, int64_t i, {T} v, int line) {{\n    if (i < 0 || i > l->len) dan_index_error(i, l->len, line);\n    {S}_push(l, v);\n    {T} last = l->items[l->len - 1];\n    memmove(&l->items[i + 1], &l->items[i], (size_t)(l->len - 1 - i) * sizeof({T}));\n    l->items[i] = last;\n}}\n\nstatic void {S}_remove({S} *l, int64_t i, int line) {{\n    if (i < 0 || i >= l->len) dan_index_error(i, l->len, line);\n    {T} old = l->items[i];\n    memmove(&l->items[i], &l->items[i + 1], (size_t)(l->len - i - 1) * sizeof({T}));\n    l->len--;\n    {RL}(old);\n    (void)old;\n}}\n\n/* \320\275\320\276\320\262\321\213\320\271 \321\201\320\277\320\270\321\201\320\276\320\272 \321\201 \321\202\320\265\320\274\320\270 \320\266\320\265 \321\215\320\273\320\265\320\274\320\265\320\275\321\202\320\260\320\274\320\270; \321\215\320\273\320\265\320\274\320\265\320\275\321\202\321\213 \320\277\320\276\320\273\321\203\321\207\320\260\321\216\321\202 \320\265\321\211\321\221 \320\276\320\264\320\275\320\276 \320\274\320\265\321\201\321\202\320\276 \321\205\321\200\320\260\320\275\320\265\320\275\320\270\321\217 */\nstatic {S} *{S}_copy(const {S} *l) {{\n    return {S}_from(l->len, l->items);\n}}\n\nstatic inline {S} *{S}_share({S} *l) {{ if (l) dan_hdr_share(&l->h); return l; }}\nstatic inline void {S}_release({S} *l) {{ if (l) dan_hdr_release(&l->h, {S}_destroy); }}\nstatic inline void {S}_give({S} *l) {{ if (l) dan_hdr_give(&l->h, {S}_destroy); }}\n\n/* \320\274\320\265\321\201\321\202\320\276 *pp \321\201\320\276\320\261\320\270\321\200\320\260\320\265\321\202\321\201\321\217 \320\270\320\267\320\274\320\265\320\275\320\270\321\202\321\214 \321\201\320\277\320\270\321\201\320\276\320\272: \320\265\321\201\320\273\320\270 \321\201\320\277\320\270\321\201\320\276\320\272 \321\205\321\200\320\260\320\275\320\270\321\202\321\201\321\217 \320\270 \320\262 \320\264\321\200\321\203\320\263\320\270\321\205\n   \320\274\320\265\321\201\321\202\320\260\321\205, \320\274\320\265\321\201\321\202\320\276 \320\277\320\276\320\273\321\203\321\207\320\260\320\265\321\202 \321\201\320\276\320\261\321\201\321\202\320\262\320\265\320\275\320\275\321\203\321\216 \320\272\320\276\320\277\320\270\321\216 */\nstatic {S} *{S}_mut({S} **pp) {{\n    {S} *l = *pp;\n    if (l->h.rc > 1) {{\n        {S} *r = {S}_copy(l);\n        r->h.rc = 1;\n        l->h.rc--;\n        *pp = r;\n        return r;\n    }}\n    return l;\n}}\n\nstatic {S} *{S}_reversed(const {S} *l) {{\n    {S} *r = {S}_copy(l);\n    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) {{ {T} t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t; }}\n    return r;\n}}\n\n/* elements a..b inclusive; b == a - 1 gives an empty list */\nstatic {S} *{S}_slice(const {S} *l, int64_t a, int64_t b, int line) {{\n    if (a < 0 || a > l->len) dan_index_error(a, l->len, line);\n    if (b < a - 1 || b >= l->len) dan_index_error(b, l->len, line);\n    return {S}_from(b - a + 1, l->items + a);\n}}\n\nstatic dan_str {S}_str(const {S} *l) {{\n    dan_buf b = {{ NULL, 0, 0 }};\n    dan_buf_add(&b, \"[\");\n    for (int64_t i = 0; i < l->len; i++) {{\n        if (i) dan_buf_add(&b, \", \");\n        dan_buf_add(&b, {\321\201\321\202\321\200\320\276\320\272\320\260_\321\215\320\273\320\265\320\274\320\265\320\275\321\202\320\260}(l->items[i]));\n    }}\n    dan_buf_add(&b, \"]\");\n    return dan_buf_str(&b);\n}}\n");
DAN_STATIC_STR(dan_lit_2158, "\n/* ---- dictionaries: hashing ---- */\nstatic uint64_t dan_hash_i(int64_t v) {\n    uint64_t z = (uint64_t)v + 0x9E3779B97F4A7C15ULL;\n    z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;\n    z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;\n    return z ^ (z >> 31);\n}\nstatic uint64_t dan_hash_s(dan_str s) {\n    uint64_t h = 0xCBF29CE484222325ULL;\n    for (const unsigned char *p = (const unsigned char *)s; *p; p++) { h ^= *p; h *= 0x100000001B3ULL; }\n    return dan_hash_i((int64_t)h);\n}\nstatic uint64_t dan_hash_r(dan_rat r) { return dan_hash_i(r.n) * 31 + dan_hash_i(r.d); }\nstatic void dan_key_error(dan_str key, int line) {\n    dan_buf b = { NULL, 0, 0 };\n    dan_buf_add(&b, DAN_MSG_NO_KEY);\n    dan_buf_add(&b, key);\n    dan_error(b.s, line);\n}\n");
DAN_STATIC_STR(dan_lit_2159, "\nstatic {D} *{D}_share({D} *d);\nstatic void {D}_release({D} *d);\nstatic void {D}_give({D} *d);\nstatic dan_str {D}_str(const {D} *d);\nstatic void {D}_write(const {D} *d);\n");
DAN_STATIC_STR(dan_lit_2160, "\n/* ---- dictionary {\320\276\320\277\320\270\321\201\320\260\320\275\320\270\320\265} ---- */\nstruct {D} {{ dan_hdr h; int64_t len, n, cap, slots; {K} *keys; {V} *vals; uint64_t *hashes; bool *alive; int64_t *index; }};\n\nstatic void {D}_destroy(dan_hdr *h) {{\n    {D} *d = ({D} *)(void *)h;\n    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) {{ {RK}(d->keys[e]); {RV}(d->vals[e]); }}\n    dan_free(d->hashes);\n    dan_free(d);\n}}\nstatic {D} *{D}_new(void) {{\n    {D} *d = dan_alloc(sizeof *d);\n    dan_hdr_new(&d->h, {D}_destroy);\n    d->len = d->n = d->cap = d->slots = 0;\n    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;\n    return d;\n}}\nstatic {D} *{D}_new_detached(void) {{\n    {D} *d = dan_alloc(sizeof *d);\n    dan_hdr_detached(&d->h);\n    d->len = d->n = d->cap = d->slots = 0;\n    d->keys = NULL; d->vals = NULL; d->hashes = NULL; d->alive = NULL; d->index = NULL;\n    return d;\n}}\nstatic {D} *{D}_share({D} *d) {{ if (d) dan_hdr_share(&d->h); return d; }}\nstatic void {D}_release({D} *d) {{ if (d) dan_hdr_release(&d->h, {D}_destroy); }}\nstatic void {D}_give({D} *d) {{ if (d) dan_hdr_give(&d->h, {D}_destroy); }}\n\n/* \320\262\321\201\320\265 \321\207\320\260\321\201\321\202\320\270 \321\201\320\273\320\276\320\262\320\260\321\200\321\217 - \320\262 \320\276\320\264\320\275\320\276\320\274 \320\261\320\273\320\276\320\272\320\265 \320\277\320\260\320\274\321\217\321\202\320\270 (\320\276\320\264\320\275\320\276 \320\262\321\213\320\264\320\265\320\273\320\265\320\275\320\270\320\265 \320\262\320\274\320\265\321\201\321\202\320\276 \320\277\321\217\321\202\320\270): \320\276\321\202\320\277\320\265\321\207\320\260\321\202\320\272\320\270,\n   \321\202\320\260\320\261\320\273\320\270\321\206\320\260 \320\277\320\276\320\270\321\201\320\272\320\260, \320\272\320\273\321\216\321\207\320\270, \320\267\320\275\320\260\321\207\320\265\320\275\320\270\321\217 \320\270 \320\277\321\200\320\270\320\267\320\275\320\260\320\272\320\270 \302\253\320\267\320\260\320\277\320\270\321\201\321\214 \320\265\321\201\321\202\321\214\302\273 \320\275\320\260 cap \320\267\320\260\320\277\320\270\321\201\320\265\320\271 */\nstatic void {D}_block({D} *d, int64_t cap) {{\n    int64_t s = 8;\n    while (s < 2 * cap) s *= 2;\n    size_t c = (size_t)cap, kb = (sizeof({K}) * c + 7) & ~(size_t)7, vb = (sizeof({V}) * c + 7) & ~(size_t)7;\n    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);\n    d->hashes = (uint64_t *)(void *)b;\n    d->index = (int64_t *)(void *)(b + 8 * c);\n    d->keys = ({K} *)(void *)(b + 8 * c + 8 * (size_t)s);\n    d->vals = ({V} *)(void *)(b + 8 * c + 8 * (size_t)s + kb);\n    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);\n    d->cap = cap;\n    d->slots = s;\n}}\nstatic void {D}_reindex({D} *d) {{\n    int64_t s = d->slots;\n    for (int64_t i = 0; i < s; i++) d->index[i] = -1;\n    for (int64_t e = 0; e < d->n; e++) {{\n        if (!d->alive[e]) continue;\n        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));\n        while (d->index[p] >= 0) p = (p + 1) & (s - 1);\n        d->index[p] = e;\n    }}\n}}\nstatic int64_t {D}_lookup(const {D} *d, {K} k, uint64_t h) {{\n    if (!d->slots) return -1;\n    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {{\n        int64_t e = d->index[p];\n        if (e < 0) return -1;\n        if (d->alive[e] && d->hashes[e] == h) {{ {K} a = d->keys[e], b = k; if ({EQ_K}) return e; }}\n    }}\n}}\nstatic void {D}_grow({D} *d) {{   /* \321\203\320\261\320\270\321\200\320\260\320\265\321\202 \321\203\320\264\320\260\320\273\321\221\320\275\320\275\321\213\320\265 \320\267\320\260\320\277\320\270\321\201\320\270 \320\270 \321\203\320\262\320\265\320\273\320\270\321\207\320\270\320\262\320\260\320\265\321\202 \321\202\320\260\320\261\320\273\320\270\321\206\321\203 */\n    int64_t cap = d->len * 2 < 8 \? 8 : d->len * 2, m = 0;\n    {K} *keys = d->keys; {V} *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;\n    int64_t n = d->n;\n    {D}_block(d, cap);\n    for (int64_t e = 0; e < n; e++) {{\n        if (!alive[e]) continue;\n        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;\n    }}\n    dan_free(hashes);\n    d->n = m;\n    {D}_reindex(d);\n}}\nstatic void {D}_put({D} *d, {K} k, {V} v) {{\n    uint64_t h = {HASH};\n    int64_t e = {D}_lookup(d, k, h);\n    if (e >= 0) {{ {V} old = d->vals[e]; d->vals[e] = {SV}(v); {RV}(old); (void)old; return; }}\n    if (d->n == d->cap) {D}_grow(d);\n    e = d->n++;\n    d->keys[e] = {SK}(k); d->vals[e] = {SV}(v); d->hashes[e] = h; d->alive[e] = true; d->len++;\n    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));\n    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);\n    d->index[p] = e;\n}}\n/* \320\267\320\260\320\277\320\270\321\201\321\214 \320\262 \320\275\320\276\320\262\321\213\320\271 \321\201\320\273\320\276\320\262\320\260\321\200\321\214 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\320\271, \320\272\320\276\321\202\320\276\321\200\321\213\320\265 \321\203\320\266\320\265 \321\203\321\207\321\202\320\265\320\275\321\213 (\320\272\320\276\320\277\320\270\321\217 \320\264\320\273\321\217 \320\267\320\260\320\264\320\260\321\207\320\270) */\nstatic void {D}_put_raw({D} *d, {K} k, {V} v) {{\n    uint64_t h = {HASH};\n    if (d->n == d->cap) {D}_grow(d);\n    int64_t e = d->n++;\n    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;\n    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));\n");
DAN_STATIC_STR(dan_lit_2161, "    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);\n    d->index[p] = e;\n}}\n/* \320\274\320\265\321\201\321\202\320\276 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\321\217 \320\277\320\276 \320\272\320\273\321\216\321\207\321\203; \320\265\321\201\320\273\320\270 \320\272\320\273\321\216\321\207\320\260 \320\275\320\265\321\202, \320\267\320\260\320\277\320\270\321\201\321\214 \321\201\320\276\320\267\320\264\320\260\321\221\321\202\321\201\321\217 \321\201\320\276 \320\267\320\275\320\260\321\207\320\265\320\275\320\270\320\265\320\274 v (\320\276\320\264\320\275\320\276 \320\276\320\261\321\200\320\260\321\211\320\265\320\275\320\270\320\265\n   \320\262\320\274\320\265\321\201\321\202\320\276 \320\277\320\276\320\273\321\203\321\207\320\270\321\202\321\214 \320\270 \320\267\320\260\320\277\320\270\321\201\320\260\321\202\321\214) */\nstatic {V} *{D}_slot({D} *d, {K} k, {V} v) {{\n    uint64_t h = {HASH};\n    int64_t e = {D}_lookup(d, k, h);\n    if (e < 0) {{\n        if (d->n == d->cap) {D}_grow(d);\n        e = d->n++;\n        d->keys[e] = {SK}(k); d->vals[e] = {SV}(v); d->hashes[e] = h; d->alive[e] = true; d->len++;\n        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));\n        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);\n        d->index[p] = e;\n    }}\n    return &d->vals[e];\n}}\nstatic {D} *{D}_from(int64_t n, const {K} *ks, const {V} *vs) {{\n    {D} *d = {D}_new();\n    for (int64_t i = 0; i < n; i++) {D}_put(d, ks[i], vs[i]);\n    return d;\n}}\nstatic {V} {D}_get(const {D} *d, {K} k, int line) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    if (e < 0) dan_key_error({\320\241\320\242\320\240\320\236\320\232\320\220_\320\232}(k), line);\n    return d->vals[e];\n}}\nstatic {V} *{D}_at({D} *d, {K} k, int line) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    if (e < 0) dan_key_error({\320\241\320\242\320\240\320\236\320\232\320\220_\320\232}(k), line);\n    return &d->vals[e];\n}}\nstatic bool {D}_contains(const {D} *d, {K} k) {{ return {D}_lookup(d, k, {HASH}) >= 0; }}\n{\320\235\320\220\320\231\320\242\320\230}static {V} {D}_get_or(const {D} *d, {K} k, {V} v) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    return e < 0 \? v : d->vals[e];\n}}\nstatic void {D}_remove({D} *d, {K} k) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    if (e >= 0) {{ d->alive[e] = false; d->len--; {RK}(d->keys[e]); {RV}(d->vals[e]); }}\n}}\nstatic {LK} *{D}_keys(const {D} *d) {{\n    {LK} *r = {LK}_from(0, NULL);\n    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) {LK}_push(r, d->keys[e]);\n    return r;\n}}\nstatic {LV} *{D}_values(const {D} *d) {{\n    {LV} *r = {LV}_from(0, NULL);\n    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) {LV}_push(r, d->vals[e]);\n    return r;\n}}\n/* \320\272\320\276\320\277\320\270\321\217 \320\264\320\273\321\217 \320\270\320\267\320\274\320\265\320\275\320\265\320\275\320\270\321\217: \320\267\320\260\320\277\320\270\321\201\320\270 \320\277\320\265\321\200\320\265\320\275\320\276\321\201\321\217\321\202\321\201\321\217 \320\262\320\274\320\265\321\201\321\202\320\265 \321\201 \320\263\320\276\321\202\320\276\320\262\321\213\320\274\320\270 \320\276\321\202\320\277\320\265\321\207\320\260\321\202\320\272\320\260\320\274\320\270 (\320\261\320\265\320\267 \320\277\320\276\320\262\321\202\320\276\321\200\320\275\320\276\320\263\320\276\n   \320\262\321\213\321\207\320\270\321\201\320\273\320\265\320\275\320\270\321\217), \320\274\320\265\321\201\321\202\320\276 - \321\201 \320\267\320\260\320\277\320\260\321\201\320\276\320\274 \320\262\320\264\320\262\320\276\320\265, \321\207\321\202\320\276\320\261\321\213 \321\201\320\273\320\265\320\264\321\203\321\216\321\211\320\260\321\217 \320\267\320\260\320\277\320\270\321\201\321\214 \320\275\320\265 \320\277\320\265\321\200\320\265\321\201\321\202\321\200\320\260\320\270\320\262\320\260\320\273\320\260 \321\202\320\260\320\261\320\273\320\270\321\206\321\203 */\nstatic {D} *{D}_copy(const {D} *d) {{\n    {D} *r = {D}_new();\n    if (d->len == 0) return r;\n    int64_t cap = d->len * 2 < 8 \? 8 : d->len * 2, m = 0;\n    {D}_block(r, cap);\n    for (int64_t e = 0; e < d->n; e++) {{\n        if (!d->alive[e]) continue;\n        r->keys[m] = {SK}(d->keys[e]); r->vals[m] = {SV}(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;\n    }}\n    r->n = r->len = m;\n    {D}_reindex(r);\n    return r;\n}}\nstatic {D} *{D}_mut({D} **pp) {{\n    {D} *d = *pp;\n    if (d->h.rc > 1) {{ {D} *r = {D}_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }}\n    return d;\n}}\nstatic dan_str {D}_str(const {D} *d) {{\n    dan_buf b = {{ NULL, 0, 0 }};\n    dan_buf_add(&b, \"{{\");\n    bool first = true;\n    for (int64_t e = 0; e < d->n; e++) {{\n        if (!d->alive[e]) continue;\n        if (!first) dan_buf_add(&b, \", \");\n        first = false;\n        dan_buf_add(&b, {\320\241\320\242\320\240\320\236\320\232\320\220_\320\232}(d->keys[e]));\n        dan_buf_add(&b, \": \");\n        dan_buf_add(&b, {\320\241\320\242\320\240\320\236\320\232\320\220_\320\227}(d->vals[e]));\n    }}\n    dan_buf_add(&b, \"}}\");\n    return dan_buf_str(&b);\n}}\nstatic void {D}_write(const {D} *d) {{ fputs({D}_str(d), stdout); }}\n");
DAN_STATIC_STR(dan_lit_2162, "\nstatic {O} {D}_find(const {D} *d, {K} k) {{\n    int64_t e = {D}_lookup(d, k, {HASH});\n    return e < 0 \? {O}_none() : {O_SOME}(d->vals[e]);\n}}\n");
DAN_STATIC_STR(dan_lit_2163, "\nstatic bool {D}_eq(const {D} *x, const {D} *y) {{\n    if (x->len != y->len) return false;\n    for (int64_t e = 0; e < x->n; e++) {{\n        if (!x->alive[e]) continue;\n        int64_t f = {D}_lookup(y, x->keys[e], x->hashes[e]);\n        if (f < 0) return false;\n        {V} a = x->vals[e]; {V} b = y->vals[f];\n        if (!({EQ_V})) return false;\n    }}\n    return true;\n}}\n");
DAN_STATIC_STR(dan_lit_2164, "\nstatic int64_t {S}_find(const {S} *l, {T} b) {{\n    for (int64_t i = 0; i < l->len; i++) {{ {T} a = l->items[i]; if ({EQ}) return i; }}\n    return -1;\n}}\nstatic bool {S}_contains(const {S} *l, {T} b) {{ return {S}_find(l, b) >= 0; }}\nstatic bool {S}_eq(const {S} *x, const {S} *y) {{\n    if (x->len != y->len) return false;\n    for (int64_t i = 0; i < x->len; i++) {{ {T} a = x->items[i]; {T} b = y->items[i]; if (!({EQ})) return false; }}\n    return true;\n}}\n");
DAN_STATIC_STR(dan_lit_2165, "\nstatic dl_Ls *dan_str_chars(dan_str s) {\n    dl_Ls *r = dl_Ls_from(0, NULL);\n    for (const char *p = s; *p;) {\n        size_t k = dan_utf8_len_at(p);\n        dl_Ls_push(r, dan_char_str(p, k));\n        p += k;\n    }\n    return r;\n}\n\nstatic dl_Ls *dan_str_split(dan_str s, dan_str sep, int line) {\n    if (!*sep) dan_error(DAN_MSG_EMPTY_SEARCH, line);\n    dl_Ls *r = dl_Ls_from(0, NULL);\n    size_t ls = strlen(sep);\n    const char *p = s, *f;\n    while ((f = strstr(p, sep)) != NULL) { dl_Ls_push(r, dan_str_sub(p, f)); p = f + ls; }\n    dl_Ls_push(r, dan_strdup(p));\n    return r;\n}\n\n/* words separated by any spaces, tabs and line breaks */\nstatic dl_Ls *dan_str_split_ws(dan_str s) {\n    dl_Ls *r = dl_Ls_from(0, NULL);\n    const char *p = s;\n    for (;;) {\n        while (*p == ' ' || *p == '\\t' || *p == '\\n' || *p == '\\r') p++;\n        if (!*p) break;\n        const char *a = p;\n        while (*p && *p != ' ' && *p != '\\t' && *p != '\\n' && *p != '\\r') p++;\n        dl_Ls_push(r, dan_str_sub(a, p));\n    }\n    return r;\n}\n\nstatic dan_str dl_Ls_join(const dl_Ls *l, dan_str sep) {\n    dan_buf b = { NULL, 0, 0 };\n    dan_buf_add(&b, \"\");\n    for (int64_t i = 0; i < l->len; i++) {\n        if (i) dan_buf_add(&b, sep);\n        dan_buf_add(&b, l->items[i]);\n    }\n    return dan_buf_str(&b);\n}\n");
DAN_STATIC_STR(dan_lit_2166, "\n/* ---- mathematics library (basics of mathematics) ---- */\n\nstatic void dan_natural_error(const char *name, int64_t n, int line) {\n    char buf[300];\n    snprintf(buf, sizeof buf, DAN_MSG_NATURAL, name, (long long)n);\n    dan_error(buf, line);\n}\n\nstatic uint64_t dan_uabs(int64_t a) { return a < 0 \? (uint64_t)0 - (uint64_t)a : (uint64_t)a; }\n\n/* \321\207\320\265\321\200\320\265\320\267 dan_uabs: \320\267\320\260\320\277\320\270\321\201\321\214 \302\253a < 0 \? -a : a\302\273 gcc 13 \321\201 -O3 \320\262 \320\276\320\264\320\275\320\276\320\271 \320\270\320\267 \320\277\321\200\320\276\320\263\321\200\320\260\320\274\320\274 \320\277\321\200\320\265\320\262\321\200\320\260\321\211\320\260\320\273 \320\262 -a \320\277\321\200\320\270 \320\273\321\216\320\261\320\276\320\274\n   \320\267\320\275\320\260\320\272\320\265 (\320\275\320\260\321\205\320\276\320\264\320\272\320\260 \321\201\320\262\320\265\321\200\320\272\320\270 \321\201\320\261\320\276\321\200\320\276\320\272, \321\204\320\260\320\267\320\267\320\270\320\275\320\263/\320\275\320\260\321\205\320\276\320\264\320\272\320\270_\321\201\320\261\320\276\321\200\320\276\320\272/\320\267\320\265\321\200\320\275\320\276_191_18.dan) */\nstatic int64_t dan_abs_int(int64_t a, int line) {\n    if (a == INT64_MIN) dan_error(DAN_MSG_TOO_BIG, line);\n    return (int64_t)dan_uabs(a);\n}\n\nstatic double dan_abs_float(double a) { return a < 0 \? -a : (a == 0 \? 0.0 : a); }\n\nstatic bool dan_divides(int64_t a, int64_t b, int line) {\n    if (b == 0) dan_error(DAN_MSG_DIV_ZERO, line);\n    return dan_uabs(a) % dan_uabs(b) == 0;\n}\n\nstatic bool dan_even(int64_t a) { return a % 2 == 0; }\nstatic bool dan_odd(int64_t a) { return a % 2 != 0; }\n\nstatic bool dan_prime(int64_t n) {\n    if (n < 2) return false;\n    if (n < 4) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    for (int64_t d = 5; d <= n / d; d += 6)\n        if (n % d == 0 || n % (d + 2) == 0) return false;\n    return true;\n}\n\nstatic dl_Li *dan_divisors(int64_t n, int line) {\n    if (n < 1) dan_natural_error(DAN_NAME_DIVISORS, n, line);\n    dl_Li *lo = dl_Li_from(0, NULL), *hi = dl_Li_from(0, NULL);\n    for (int64_t d = 1; d <= n / d; d++) {\n        if (n % d == 0) {\n            dl_Li_push(lo, d);\n            if (d != n / d) dl_Li_push(hi, n / d);\n        }\n    }\n    for (int64_t i = hi->len - 1; i >= 0; i--) dl_Li_push(lo, hi->items[i]);\n    return lo;\n}\n\nstatic dl_Li *dan_multiples(int64_t a, int64_t count, int line) {\n    if (count < 0) dan_error(DAN_MSG_NEG_COUNT, line);\n    dl_Li *r = dl_Li_from(0, NULL);\n    for (int64_t k = 1; k <= count; k++) {\n        int64_t v;\n        if (__builtin_mul_overflow(a, k, &v)) dan_error(DAN_MSG_TOO_BIG, line);\n        dl_Li_push(r, v);\n    }\n    return r;\n}\n\nstatic dl_Li *dan_prime_factors(int64_t n, int line) {\n    if (n < 1) dan_natural_error(DAN_NAME_PRIME_FACTORS, n, line);\n    dl_Li *r = dl_Li_from(0, NULL);\n    while (n % 2 == 0) { dl_Li_push(r, 2); n /= 2; }\n    for (int64_t d = 3; d <= n / d; d += 2)\n        while (n % d == 0) { dl_Li_push(r, d); n /= d; }\n    if (n > 1) dl_Li_push(r, n);\n    return r;\n}\n\nstatic uint64_t dan_gcd_u(uint64_t a, uint64_t b) {\n    while (b) { uint64_t t = a % b; a = b; b = t; }\n    return a;\n}\n\nstatic int64_t dan_gcd(int64_t a, int64_t b, int line) {\n    uint64_t g = dan_gcd_u(dan_uabs(a), dan_uabs(b));\n    if (g > (uint64_t)INT64_MAX) dan_error(DAN_MSG_TOO_BIG, line);\n    return (int64_t)g;\n}\n\nstatic int64_t dan_lcm(int64_t a, int64_t b, int line) {\n    if (a == 0 || b == 0) return 0;\n    uint64_t ua = dan_uabs(a), ub = dan_uabs(b);\n    uint64_t r;\n    if (__builtin_mul_overflow(ua / dan_gcd_u(ua, ub), ub, &r) || r > (uint64_t)INT64_MAX)\n        dan_error(DAN_MSG_TOO_BIG, line);\n    return (int64_t)r;\n}\n\nstatic int64_t dan_gcd_list(const dl_Li *l, int line) {\n    if (l->len == 0) dan_conv_error(DAN_MSG_EMPTY_LIST, DAN_NAME_GCD, line);\n    int64_t g = dan_gcd(l->items[0], 0, line);\n    for (int64_t i = 1; i < l->len; i++) g = dan_gcd(g, l->items[i], line);\n    return g;\n}\n\nstatic int64_t dan_lcm_list(const dl_Li *l, int line) {\n    if (l->len == 0) dan_conv_error(DAN_MSG_EMPTY_LIST, DAN_NAME_LCM, line);\n    int64_t m = dan_abs_int(l->items[0], line);\n    for (int64_t i = 1; i < l->len; i++) m = dan_lcm(m, l->items[i], line);\n    return m;\n}\n\nstatic dl_Li *dan_digits(int64_t n) {\n    uint64_t u = dan_uabs(n);\n    dl_Li *r = dl_Li_from(0, NULL);\n    do { dl_Li_push(r, (int64_t)(u % 10)); u /= 10; } while (u);\n    for (int64_t i = 0, j = r->len - 1; i < j; i++, j--) {\n        int64_t t = r->items[i]; r->items[i] = r->items[j]; r->items[j] = t;\n    }\n    return r;\n}\n\nstatic int64_t dan_digit_sum(int64_t n) {\n");
DAN_STATIC_STR(dan_lit_2167, "    uint64_t u = dan_uabs(n);\n    int64_t s = 0;\n    do { s += (int64_t)(u % 10); u /= 10; } while (u);\n    return s;\n}\n\n/* 635 -> [600, 30, 5]; the sign of a negative number is kept: -635 -> [-600, -30, -5] */\nstatic dl_Li *dan_place_values(int64_t n) {\n    dl_Li *r = dl_Li_from(0, NULL);\n    if (n == 0) { dl_Li_push(r, 0); return r; }\n    int64_t place = 1;\n    dl_Li *low = dl_Li_from(0, NULL);\n    while (n != 0) {\n        int64_t digit = n % 10;          /* same sign as n */\n        if (digit != 0) dl_Li_push(low, digit * place);\n        n /= 10;\n        if (n != 0) place *= 10;\n    }\n    for (int64_t i = low->len - 1; i >= 0; i--) dl_Li_push(r, low->items[i]);\n    return r;\n}\n");
DAN_STATIC_STR(dan_lit_2168, "typedef struct { const char *name; int kind; double num, den; } dan_unit;\nstatic const dan_unit dan_units[] = {\n    { \"\\320\\274\\320\\274\", 1, 1.0, 1000.0 },\n    { \"\\321\\201\\320\\274\", 1, 1.0, 100.0 },\n    { \"\\320\\264\\320\\274\", 1, 1.0, 10.0 },\n    { \"\\320\\274\", 1, 1.0, 1.0 },\n    { \"\\320\\272\\320\\274\", 1, 1000.0, 1.0 },\n    { \"\\320\\274\\320\\263\", 2, 1.0, 1000.0 },\n    { \"\\320\\263\", 2, 1.0, 1.0 },\n    { \"\\320\\272\\320\\263\", 2, 1000.0, 1.0 },\n    { \"\\321\\206\", 2, 100000.0, 1.0 },\n    { \"\\321\\202\", 2, 1000000.0, 1.0 },\n    { \"\\321\\201\", 3, 1.0, 1.0 },\n    { \"\\321\\201\\320\\265\\320\\272\", 3, 1.0, 1.0 },\n    { \"\\320\\274\\320\\270\\320\\275\", 3, 60.0, 1.0 },\n    { \"\\321\\207\", 3, 3600.0, 1.0 },\n    { \"\\321\\207\\320\\260\\321\\201\", 3, 3600.0, 1.0 },\n    { \"\\321\\201\\321\\203\\321\\202\", 3, 86400.0, 1.0 },\n    { \"\\321\\201\\321\\203\\321\\202\\320\\272\\320\\270\", 3, 86400.0, 1.0 },\n    { \"\\320\\275\\320\\265\\320\\264\", 3, 604800.0, 1.0 },\n    { \"\\320\\274\\320\\274\\302\\262\", 4, 1.0, 1000000.0 },\n    { \"\\320\\274\\320\\2742\", 4, 1.0, 1000000.0 },\n    { \"\\321\\201\\320\\274\\302\\262\", 4, 1.0, 10000.0 },\n    { \"\\321\\201\\320\\2742\", 4, 1.0, 10000.0 },\n    { \"\\320\\264\\320\\274\\302\\262\", 4, 1.0, 100.0 },\n    { \"\\320\\264\\320\\2742\", 4, 1.0, 100.0 },\n    { \"\\320\\274\\302\\262\", 4, 1.0, 1.0 },\n    { \"\\320\\2742\", 4, 1.0, 1.0 },\n    { \"\\320\\260\", 4, 100.0, 1.0 },\n    { \"\\320\\260\\321\\200\", 4, 100.0, 1.0 },\n    { \"\\321\\201\\320\\276\\321\\202\\320\\272\\320\\260\", 4, 100.0, 1.0 },\n    { \"\\320\\263\\320\\260\", 4, 10000.0, 1.0 },\n    { \"\\320\\272\\320\\274\\302\\262\", 4, 1000000.0, 1.0 },\n    { \"\\320\\272\\320\\2742\", 4, 1000000.0, 1.0 },\n    { \"\\320\\274\\320\\274\\302\\263\", 5, 1.0, 1000000000.0 },\n    { \"\\320\\274\\320\\2743\", 5, 1.0, 1000000000.0 },\n    { \"\\321\\201\\320\\274\\302\\263\", 5, 1.0, 1000000.0 },\n    { \"\\321\\201\\320\\2743\", 5, 1.0, 1000000.0 },\n    { \"\\320\\274\\320\\273\", 5, 1.0, 1000000.0 },\n    { \"\\320\\264\\320\\274\\302\\263\", 5, 1.0, 1000.0 },\n    { \"\\320\\264\\320\\2743\", 5, 1.0, 1000.0 },\n    { \"\\320\\273\", 5, 1.0, 1000.0 },\n    { \"\\320\\274\\302\\263\", 5, 1.0, 1.0 },\n    { \"\\320\\2743\", 5, 1.0, 1.0 },\n    { \"\\320\\274/\\321\\201\", 6, 1.0, 1.0 },\n    { \"\\320\\274/\\320\\274\\320\\270\\320\\275\", 6, 1.0, 60.0 },\n    { \"\\320\\272\\320\\274/\\321\\207\", 6, 1000.0, 3600.0 },\n    { \"\\320\\272\\320\\274/\\320\\274\\320\\270\\320\\275\", 6, 1000.0, 60.0 },\n};\n\n/* ---- fractions, rounding, roots, units ---- */\n\nstatic dan_rat dan_rat_abs(dan_rat a, int line) { return a.n < 0 \? dan_rat_neg(a, line) : a; }\n\n/* 7/3 -> \"2 1/3\", -7/3 -> \"-2 1/3\", 1/3 -> \"1/3\", 6/3 -> \"2\" */\nstatic dan_str dan_mixed_str(dan_rat a) {\n    char b[96];\n    uint64_t un = a.n < 0 \? (uint64_t)0 - (uint64_t)a.n : (uint64_t)a.n;\n    uint64_t whole = un / (uint64_t)a.d, rest = un % (uint64_t)a.d;\n    const char *sign = a.n < 0 \? \"-\" : \"\";\n    if (rest == 0) snprintf(b, sizeof b, \"%s%llu\", sign, (unsigned long long)whole);\n    else if (whole == 0) snprintf(b, sizeof b, \"%s%llu/%lld\", sign, (unsigned long long)rest, (long long)a.d);\n    else snprintf(b, sizeof b, \"%s%llu %llu/%lld\", sign, (unsigned long long)whole,\n                  (unsigned long long)rest, (long long)a.d);\n    return dan_strdup(b);\n}\n\nstatic dan_rat dan_mixed_make(int64_t whole, int64_t num, int64_t den, int line) {\n    if (num < 0 || den <= 0) dan_error(DAN_MSG_MIXED, line);\n    dan_rat part = dan_rat_of(num, den, line);\n    dan_rat w = dan_rat_from_int(whole < 0 \? -whole : whole, line);\n    dan_rat r = dan_rat_add(w, part, line);\n    return whole < 0 \? dan_rat_neg(r, line) : r;\n}\n\n/* Decimal notation with the repeating part in brackets: 1/6 -> \"0,1(6)\" */\nstatic dan_str dan_periodic(dan_rat a, int line) {\n    uint64_t un = a.n < 0 \? (uint64_t)0 - (uint64_t)a.n : (uint64_t)a.n;\n    uint64_t d = (uint64_t)a.d;\n    char head[48];\n    snprintf(head, sizeof head, \"%s%llu\", a.n < 0 \? \"-\" : \"\", (unsigned long long)(un / d));\n    uint64_t r = un % d;\n    if (r == 0) return dan_strdup(head);\n    /* pre-period length: the larger power of 2 or 5 in the denominator */\n    int c2 = 0, c5 = 0;\n    uint64_t t = d;\n");
DAN_STATIC_STR(dan_lit_2169, "    while (t % 2 == 0) { t /= 2; c2++; }\n    while (t % 5 == 0) { t /= 5; c5++; }\n    int pre = c2 > c5 \? c2 : c5;\n    size_t cap = 64, len = 0;\n    char *digits = dan_alloc(cap);\n    for (int i = 0; i < pre; i++) {\n        dan_u128 x = (dan_u128)r * 10;\n        if (len + 2 >= cap) { cap *= 2; digits = dan_realloc(digits, cap); }\n        digits[len++] = (char)('0' + (int)(x / d));\n        r = (uint64_t)(x % d);\n    }\n    size_t period_start = len;\n    if (r != 0) {\n        uint64_t start = r;\n        do {\n            dan_u128 x = (dan_u128)r * 10;\n            if (len + 4 >= cap) { cap *= 2; digits = dan_realloc(digits, cap); }\n            digits[len++] = (char)('0' + (int)(x / d));\n            r = (uint64_t)(x % d);\n            if (len - period_start > 100000) dan_error(DAN_MSG_PERIOD_LONG, line);\n        } while (r != start);\n    }\n    size_t hl = strlen(head);\n    char *out = dan_str_new(hl + len + 3);\n    memcpy(out, head, hl);\n    out[hl] = ',';\n    memcpy(out + hl + 1, digits, period_start);\n    size_t pos = hl + 1 + period_start;\n    if (len > period_start) {\n        out[pos++] = '(';\n        memcpy(out + pos, digits + period_start, len - period_start);\n        pos += len - period_start;\n        out[pos++] = ')';\n    }\n    out[pos] = 0;\n    dan_free(digits);\n    return out;\n}\n\n/* School rounding (half away from zero) on the shortest decimal form of the\n   number, so that 2.675 rounds to 2.68 exactly as written. */\nstatic double dan_round_decimal(double v, int64_t places) {\n    if (v != v || v - v != 0 || places > 17) return v;\n    char buf[64];\n    for (int prec = 0; prec <= 16; prec++) {\n        snprintf(buf, sizeof buf, \"%.*e\", prec, v);\n        if (strtod(buf, NULL) == v) break;\n    }\n    const char *p = buf;\n    int neg = 0;\n    if (*p == '-') { neg = 1; p++; }\n    char digits[32];\n    int nd = 0;\n    for (; *p && *p != 'e'; p++) if (*p >= '0' && *p <= '9') digits[nd++] = *p;\n    long e10 = strtol(p + 1, NULL, 10);\n    long keep = e10 + 1 + (long)places;      /* digits kept before the cut */\n    if (keep >= nd) return v;\n    if (keep < 0) return neg \? -0.0 : 0.0;\n    uint64_t kept = 0;\n    for (long i = 0; i < keep; i++) kept = kept * 10 + (uint64_t)(digits[i] - '0');\n    if (digits[keep] >= '5') kept++;\n    char out[64];\n    snprintf(out, sizeof out, \"%s%llue%ld\", neg \? \"-\" : \"\", (unsigned long long)kept, e10 + 1 - keep);\n    return strtod(out, NULL);\n}\n\nstatic int64_t dan_round_float(double v, int line) {\n    double r = dan_round_decimal(v, 0);\n    return dan_float_to_int(r, line);\n}\n\nstatic int64_t dan_round_rat(dan_rat a, int line) {\n    (void)line;\n    dan_i128 n = a.n < 0 \? -(dan_i128)a.n : a.n;\n    dan_i128 q = (2 * n + a.d) / (2 * (dan_i128)a.d);\n    return (int64_t)(a.n < 0 \? -q : q);\n}\n\nstatic double dan_round_float_places(double v, int64_t places, int line) {\n    (void)line;\n    return dan_round_decimal(v, places);\n}\n\nstatic dan_i128 dan_pow10_128(int64_t k) { dan_i128 r = 1; while (k-- > 0) r *= 10; return r; }\n\nstatic double dan_round_rat_places(dan_rat a, int64_t places, int line) {\n    if (places > 18 || places < -18) return dan_round_decimal(dan_rat_to_float(a), places);\n    dan_i128 n = a.n < 0 \? -(dan_i128)a.n : a.n, d = a.d;\n    if (places >= 0) n *= dan_pow10_128(places); else d *= dan_pow10_128(-places);\n    dan_i128 q = (2 * n + d) / (2 * d);\n    double r = places >= 0 \? (double)q / (double)dan_pow10_128(places) : (double)q * (double)dan_pow10_128(-places);\n    (void)line;\n    r = dan_round_decimal(r, places);\n    return a.n < 0 \? -r : r;\n}\n\n/* Rounding an integer to tens, hundreds, ...: (1234, -2) -> 1200 */\nstatic int64_t dan_round_int_places(int64_t v, int64_t places, int line) {\n    if (places >= 0) return v;\n    if (places < -18) return 0;\n    dan_i128 p = dan_pow10_128(-places);\n    dan_i128 n = v < 0 \? -(dan_i128)v : v;\n    dan_i128 q = (2 * n + p) / (2 * p) * p;\n    if (q > INT64_MAX) dan_error(DAN_MSG_TOO_BIG, line);\n    return (int64_t)(v < 0 \? -q : q);\n}\n\n");
DAN_STATIC_STR(dan_lit_2170, "static double dan_sqrt(double v, int line) {\n    if (v < 0) dan_error(DAN_MSG_SQRT_NEG, line);\n    return sqrt(v);\n}\n\nstatic int64_t dan_isqrt(int64_t n, int line) {\n    if (n < 0) dan_error(DAN_MSG_SQRT_NEG, line);\n    uint64_t r = (uint64_t)sqrt((double)n);\n    while (r * r > (uint64_t)n) r--;\n    while ((r + 1) * (r + 1) <= (uint64_t)n) r++;\n    return (int64_t)r;\n}\n\nstatic const dan_unit *dan_find_unit(dan_str name, int line) {\n    for (size_t i = 0; i < sizeof dan_units / sizeof dan_units[0]; i++)\n        if (strcmp(dan_units[i].name, name) == 0) return &dan_units[i];\n    dan_conv_error(DAN_MSG_UNIT_UNKNOWN, name, line);\n    return NULL;\n}\n\nstatic double dan_convert_units(double v, dan_str from, dan_str to, int line) {\n    const dan_unit *a = dan_find_unit(from, line), *b = dan_find_unit(to, line);\n    if (a->kind != b->kind) {\n        char buf[300];\n        snprintf(buf, sizeof buf, DAN_MSG_UNIT_KIND, from, to);\n        dan_error(buf, line);\n    }\n    double r = v * (a->num * b->den) / (a->den * b->num);\n    char t[64];\n    snprintf(t, sizeof t, \"%.15g\", r);          /* remove binary noise: 0.30000000000000004 */\n    return strtod(t, NULL);\n}\n\n\nstatic int dan_cmp_i(int64_t x, int64_t y) { return (x > y) - (x < y); }\nstatic int dan_qcmp_i(const void *a, const void *b) { return dan_cmp_i(*(const int64_t *)a, *(const int64_t *)b); }\nstatic dl_Li *dan_sorted_i(const dl_Li *l) {\n    dl_Li *r = dl_Li_from(l->len, l->items);\n    qsort(r->items, (size_t)r->len, sizeof(int64_t), dan_qcmp_i);\n    return r;\n}\n\nstatic dl_Li *dan_set_i(const dl_Li *l) {\n    dl_Li *s = dan_sorted_i(l);\n    int64_t k = 0;\n    for (int64_t i = 0; i < s->len; i++)\n        if (k == 0 || dan_cmp_i(s->items[k - 1], s->items[i]) != 0) s->items[k++] = s->items[i];\n        else DAN_NOREL(s->items[i]);\n    s->len = k;\n    return s;\n}\nstatic bool dan_contains_i(int64_t x, const dl_Li *l) {\n    for (int64_t i = 0; i < l->len; i++) if (dan_cmp_i(l->items[i], x) == 0) return true;\n    return false;\n}\nstatic dl_Li *dan_union_i(const dl_Li *a, const dl_Li *b) {\n    dl_Li *r = dl_Li_from(a->len, a->items);\n    for (int64_t i = 0; i < b->len; i++) dl_Li_push(r, b->items[i]);\n    return dan_set_i(r);\n}\nstatic dl_Li *dan_intersection_i(const dl_Li *a, const dl_Li *b) {\n    dl_Li *r = dl_Li_from(0, NULL);\n    for (int64_t i = 0; i < a->len; i++) if (dan_contains_i(a->items[i], b)) dl_Li_push(r, a->items[i]);\n    return dan_set_i(r);\n}\nstatic dl_Li *dan_difference_i(const dl_Li *a, const dl_Li *b) {\n    dl_Li *r = dl_Li_from(0, NULL);\n    for (int64_t i = 0; i < a->len; i++) if (!dan_contains_i(a->items[i], b)) dl_Li_push(r, a->items[i]);\n    return dan_set_i(r);\n}\nstatic bool dan_subset_i(const dl_Li *a, const dl_Li *b) {\n    for (int64_t i = 0; i < a->len; i++) if (!dan_contains_i(a->items[i], b)) return false;\n    return true;\n}\n\nstatic void dan_need_items_i(const dl_Li *l, int line) { if (l->len == 0) dan_error(DAN_MSG_EMPTY_STAT, line); }\nstatic int64_t dan_sum_i(const dl_Li *l, int line) {\n    (void)line;\n    int64_t s = 0;\n    for (int64_t i = 0; i < l->len; i++) s = s + l->items[i];\n    return s;\n}\nstatic double dan_mean_i(const dl_Li *l, int line) { dan_need_items_i(l, line); return (double)dan_sum_i(l, line) / (double)l->len; }\nstatic double dan_median_i(const dl_Li *l, int line) {\n    dan_need_items_i(l, line);\n    dl_Li *s = dan_sorted_i(l);\n    int64_t m = s->len / 2;\n    if (s->len % 2 == 0) return ((double)s->items[m - 1] + (double)s->items[m]) / 2.0;\n    return (double)s->items[m];\n}\nstatic int64_t dan_min_i(const dl_Li *l, int line) {\n    dan_need_items_i(l, line);\n    int64_t r = l->items[0];\n    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_i(l->items[i], r) < 0) r = l->items[i];\n    return r;\n}\nstatic int64_t dan_max_i(const dl_Li *l, int line) {\n    dan_need_items_i(l, line);\n    int64_t r = l->items[0];\n    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_i(l->items[i], r) > 0) r = l->items[i];\n    return r;\n}\n");
DAN_STATIC_STR(dan_lit_2171, "static int64_t dan_min2_i(int64_t x, int64_t y) { return dan_cmp_i(x, y) <= 0 \? x : y; }\nstatic int64_t dan_max2_i(int64_t x, int64_t y) { return dan_cmp_i(x, y) >= 0 \? x : y; }\nstatic int64_t dan_range_i(const dl_Li *l, int line) {\n    int64_t a = dan_min_i(l, line), b = dan_max_i(l, line);\n    return b - a;\n}\n\nstatic int dan_cmp_r(dan_rat x, dan_rat y) { return dan_rat_cmp(x, y); }\nstatic int dan_qcmp_r(const void *a, const void *b) { return dan_cmp_r(*(const dan_rat *)a, *(const dan_rat *)b); }\nstatic dl_Lr *dan_sorted_r(const dl_Lr *l) {\n    dl_Lr *r = dl_Lr_from(l->len, l->items);\n    qsort(r->items, (size_t)r->len, sizeof(dan_rat), dan_qcmp_r);\n    return r;\n}\n\nstatic void dan_need_items_r(const dl_Lr *l, int line) { if (l->len == 0) dan_error(DAN_MSG_EMPTY_STAT, line); }\nstatic dan_rat dan_sum_r(const dl_Lr *l, int line) {\n    (void)line;\n    dan_rat s = dan_rat_from_int(0, line);\n    for (int64_t i = 0; i < l->len; i++) s = dan_rat_add(s, l->items[i], line);\n    return s;\n}\nstatic dan_rat dan_mean_r(const dl_Lr *l, int line) { dan_need_items_r(l, line); return dan_rat_div(dan_sum_r(l, line), dan_rat_from_int(l->len, line), line); }\nstatic dan_rat dan_median_r(const dl_Lr *l, int line) {\n    dan_need_items_r(l, line);\n    dl_Lr *s = dan_sorted_r(l);\n    int64_t m = s->len / 2;\n    if (s->len % 2 == 0) return dan_rat_div(dan_rat_add(s->items[m - 1], s->items[m], line), dan_rat_from_int(2, line), line);\n    return s->items[m];\n}\nstatic dan_rat dan_min_r(const dl_Lr *l, int line) {\n    dan_need_items_r(l, line);\n    dan_rat r = l->items[0];\n    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_r(l->items[i], r) < 0) r = l->items[i];\n    return r;\n}\nstatic dan_rat dan_max_r(const dl_Lr *l, int line) {\n    dan_need_items_r(l, line);\n    dan_rat r = l->items[0];\n    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_r(l->items[i], r) > 0) r = l->items[i];\n    return r;\n}\nstatic dan_rat dan_min2_r(dan_rat x, dan_rat y) { return dan_cmp_r(x, y) <= 0 \? x : y; }\nstatic dan_rat dan_max2_r(dan_rat x, dan_rat y) { return dan_cmp_r(x, y) >= 0 \? x : y; }\nstatic dan_rat dan_range_r(const dl_Lr *l, int line) {\n    dan_rat a = dan_min_r(l, line), b = dan_max_r(l, line);\n    return dan_rat_sub(b, a, line);\n}\n\nstatic int dan_cmp_f(double x, double y) { return (x > y) - (x < y); }\nstatic int dan_qcmp_f(const void *a, const void *b) { return dan_cmp_f(*(const double *)a, *(const double *)b); }\nstatic dl_Lf *dan_sorted_f(const dl_Lf *l) {\n    dl_Lf *r = dl_Lf_from(l->len, l->items);\n    qsort(r->items, (size_t)r->len, sizeof(double), dan_qcmp_f);\n    return r;\n}\n\nstatic void dan_need_items_f(const dl_Lf *l, int line) { if (l->len == 0) dan_error(DAN_MSG_EMPTY_STAT, line); }\nstatic double dan_sum_f(const dl_Lf *l, int line) {\n    (void)line;\n    double s = 0.0;\n    for (int64_t i = 0; i < l->len; i++) s = s + l->items[i];\n    return s;\n}\nstatic double dan_mean_f(const dl_Lf *l, int line) { dan_need_items_f(l, line); return dan_sum_f(l, line) / (double)l->len; }\nstatic double dan_median_f(const dl_Lf *l, int line) {\n    dan_need_items_f(l, line);\n    dl_Lf *s = dan_sorted_f(l);\n    int64_t m = s->len / 2;\n    if (s->len % 2 == 0) return (s->items[m - 1] + s->items[m]) / 2.0;\n    return s->items[m];\n}\nstatic double dan_min_f(const dl_Lf *l, int line) {\n    dan_need_items_f(l, line);\n    double r = l->items[0];\n    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_f(l->items[i], r) < 0) r = l->items[i];\n    return r;\n}\nstatic double dan_max_f(const dl_Lf *l, int line) {\n    dan_need_items_f(l, line);\n    double r = l->items[0];\n    for (int64_t i = 1; i < l->len; i++) if (dan_cmp_f(l->items[i], r) > 0) r = l->items[i];\n    return r;\n}\nstatic double dan_min2_f(double x, double y) { return dan_cmp_f(x, y) <= 0 \? x : y; }\nstatic double dan_max2_f(double x, double y) { return dan_cmp_f(x, y) >= 0 \? x : y; }\nstatic double dan_range_f(const dl_Lf *l, int line) {\n    double a = dan_min_f(l, line), b = dan_max_f(l, line);\n    return b - a;\n}\n\n");
