    if (e >= 0) { dl_LTproverkau2ePoleT* old = d->vals[e]; d->vals[e] = dl_LTproverkau2ePoleT_share(v); dl_LTproverkau2ePoleT_release(old); (void)old; return; }
    if (d->n == d->cap) dm_DsLTproverkau2ePoleT_grow(d);
    e = d->n++;
    d->keys[e] = dan_str_share(k); d->vals[e] = dl_LTproverkau2ePoleT_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
