static dan_rat dan_f_9_r(dan_rat a0, dan_rat a1, int line) { (void)line; return dan_rat_mul(dan_rat_from_int(2, line), dan_rat_add(a0, a1, line), line); }
static double dan_f_10_f(double a0, double a1, int line) { (void)line; return (2.0 * (a0 + a1)); }
static int64_t dan_f_11_i(int64_t a0, int64_t a1, int line) { (void)line; return (a0 * a1); }
static dan_rat dan_f_12_r(dan_rat a0, dan_rat a1, int line) { (void)line; return dan_rat_mul(a0, a1, line); }
static double dan_f_13_f(double a0, double a1, int line) { (void)line; return (a0 * a1); }
static int64_t dan_f_14_i(int64_t a0, int line) { (void)line; return (INT64_C(4) * a0); }
static dan_rat dan_f_15_r(dan_rat a0, int line) { (void)line; return dan_rat_mul(dan_rat_from_int(4, line), a0, line); }
static double dan_f_16_f(double a0, int line) { (void)line; return (4.0 * a0); }
static int64_t dan_f_17_i(int64_t a0, int line) { (void)line; return (a0 * a0); }
static dan_rat dan_f_18_r(dan_rat a0, int line) { (void)line; return dan_rat_mul(a0, a0, line); }
static double dan_f_19_f(double a0, int line) { (void)line; return (a0 * a0); }
static dan_rat dan_f_20_r(dan_rat a0, dan_rat a1, int line) { (void)line; return dan_rat_div(dan_rat_mul(a0, a1, line), dan_rat_from_int(2, line), line); }
static double dan_f_21_f(double a0, double a1, int line) { (void)line; return ((a0 * a1) / 2.0); }
static int64_t dan_f_22_i(int64_t a0, int line) { (void)line; return ((a0 * a0) * a0); }
